NAME = 'ACV: A Conservative Version'
BOOK = 'Exodus'

CHAPTERS = {
    1: {
        1: 'In ta so imena sinov Izraelovih, ki so prišli v Egipt z Jakobom; vsak je prišel z rodbino svojo:',
        2: 'Ruben, Simeon, Levi in Juda,',
        3: 'Isahar, Zebulon in Benjamin,',
        4: 'Dan in Neftali, Gad in Aser.',
        5: 'In bilo je vseh duš, ki so izšle iz ledij Jakobovih, sedemdeset; a Jožef je bil prej v Egiptu.',
        6: 'In umrl je Jožef in vsi bratje njegovi in vse to pokolenje.',
        7: 'In sinovi Izraelovi so bili plodoviti, rodili so se obilo, razmnoževali so se in postali so jako, jako mogočni; in napolnila se je zemlja ž njimi.',
        8: 'Nastopi pa v Egiptu nov kralj, ki ni poznal Jožefa.',
        9: 'Ta reče ljudstvu svojemu: Glejte, ljudstvo sinov Izraelovih je številnejše in mogočnejše od nas.',
        10: 'Dejte, pametno ravnajmo proti njemu, da se ne razmnoži, in zgodilo bi se, ako nastane vojna, da se tudi ono pridruži sovražnikom našim in se bo vojskovalo zoper nas in odšlo iz dežele.',
        11: 'Nastavijo torej nad njimi priganjače za raboto, da naj jih tlačijo pri njih težaškem delu. Zidali so pa Faraonu mesta za skladišča, Pitom in Rameses.',
        12: 'A čim bolj so jih tlačili, tem bolj so se razmnoževali, tem bolj so se razširjali: in Egipčane je bilo groza sinov Izraelovih.',
        13: 'In neusmiljeno so Egipčani priganjali sinove Izraelove k delu;',
        14: 'in grenili so jim življenje s trdim delom z ilovico in z opeko in z vsakovrstnim opravilom na polju, z vsem njih delom, katero so jim nakladali neusmiljeno.',
        15: 'In ukaže kralj egiptovski dvema hebrejskima babicama, katerih prvi je bilo ime Šifra in drugi ime Pua,',
        16: 'rekoč: Ko pomagate ženam hebrejskim pri porodu, pazite na rojenje: če je sin, usmrtite ga, če pa hči, naj ostane živa.',
        17: 'Bali sta se pa ti babici Boga in nista delali, kakor jima je bil ukazal kralj egiptovski, temuč pustili sta dečke živeti.',
        18: 'In pokliče kralj egiptovski ti babici in jima reče: Zakaj sta to storili in pustili dečke živeti?',
        19: 'Babici pa odgovorita Faraonu: Niso Hebrejke kakor egiptovske žene: ker so krepke narave, porodijo, preden pride k njim babica.',
        20: 'In Bog je dobro storil tema babicama. Ljudstvo pa se je množilo in postalo zelo mogočno.',
        21: 'In ker sta se babici bali Boga, jima je napravil hiši.',
        22: 'In zapove Faraon vsemu ljudstvu svojemu, rekoč: Vsakega sina, ki se jim narodi, vrzite v reko, a vsako hčer ohranite živo.',
    },
    2: {
        1: 'Odide pa mož iz hiše Levijeve in si vzame hčer Levijevo.',
        2: 'In žena spočne ter rodi sina, in ko vidi, da je lep, ga skriva tri mesece.',
        3: 'In ko ga ni mogla dalje skrivati, vzame zanj pletenico iz papirovega trstja in jo zamaže z ilovico in s smolo, potem položi dečka vanjo in jo dene v ločje na Nilovem bregu.',
        4: 'Njegova sestra pa se postavi oddaleč, da bi videla, kaj se bo ž njim zgodilo.',
        5: 'In pride doli hči Faraonova kopat se v reki; in njene dekle se izprehajajo poleg reke. In zagleda pletenico sredi ločja in pošlje svojo deklo, da jo prinese.',
        6: 'Ko jo pa odpre, vidi dete, in glej, deček joče. In stori se ji milo in reče: Izmed otrok Hebrejcev je ta.',
        7: 'In sestra njegova reče hčeri Faraonovi: Ali naj grem in ti pokličem ženo dojnico izmed Hebrejk, da ti odgoji to dete?',
        8: 'In hči Faraonova ji veli: Pojdi! In deklica gre in pokliče otrokovo mater.',
        9: 'In hči Faraonova ji veli: Vzemi tega otročička in odgoji mi ga, in dam ti plačilo tvoje. In žena vzame otroka, in ga je vzgajala.',
        10: 'In ko je deček odrastel, ga je privedla k hčeri Faraonovi. In bil ji je za sina in imenovala je ime njegovo Mojzes, rekoč: Ker sem ga potegnila iz vode.',
        11: 'In zgodi se v tistih dnevih, da pride Mojzes, ko je bil že velik, k bratom svojim in gleda njih težaško delo; in vidi moža Egipčana, da tepe moža Hebrejca, izmed bratov njegovih.',
        12: 'In ozre se sem in tja, in ko vidi, da ni nikogar blizu, ubije Egipčana in ga zagrebe v pesek.',
        13: 'In izide zopet drugi dan, in glej, dva moža, Hebrejca, se prepirata. In reče tistemu, ki je delal krivico: Zakaj tepeš bližnjega svojega?',
        14: 'Ta pa reče: Kdo te je postavil za kneza in sodnika nam? Misliš li me umoriti, kakor si umoril Egipčana? Tedaj se Mojzes prestraši in reče: Gotovo se je zvedela ta stvar!',
        15: 'In Faraon, ko je začul o tem dogodku, je nameraval Mojzesa umoriti. A Mojzes pobegne izpred obličja Faraonovega, in je prebival v deželi Madianski; in usede se pri nekem studencu.',
        16: 'Duhovnik madianski pa je imel sedmero hčera, ki so prišle zajemat vodo; in napolnile so korita, da bi napojile čredo očeta svojega.',
        17: 'A pridejo pastirji in jih odženo. Mojzes pa vstane in jim pomaga in napoji njih čredo.',
        18: 'In ko pridejo k Reguelu, očetu svojemu, jim reče: Zakaj ste se danes vrnile tako hitro?',
        19: 'In odgovore: Mož Egipčan nas je rešil iz rok pastirjev in tudi nam zajel vode in napojil je čredo.',
        20: 'On pa reče hčeram svojim: In kje je on? zakaj ste popustile tistega moža? Pokličite ga, da jé z nami kruh!',
        21: 'In Mojzes privoli, da ostane pri tem možu; ta pa da Mojzesu Ziforo, hčer svojo.',
        22: 'In ko porodi sina, imenuje on ime njegovo Gersom, kajti reče: Priseljenec sem v tuji zemlji.',
        23: 'In zgodi se v mnogih tistih dnevih, da umrje egiptovski kralj. In sinovi Izraelovi so zdihovali zaradi tlake in vpili so, in njih vpitje od tlačanstva je prišlo k Bogu.',
        24: 'In uslišal je Bog njih stokanje, in spomnil se je Bog svoje zaveze z Abrahamom, z Izakom in z Jakobom.',
        25: 'In Bog je pogledal na sinove Izraelove, in spoznal jih je Bog.',
    },
    3: {
        1: 'Mojzes pa je pasel čredo Jetra, tasta svojega, duhovnika madianskega. In žene čredo onkraj puščave in pride na goro Božjo, Horeb.',
        2: 'In prikaže se mu angel Gospodov v plamenu ognja iz sredi grma; in pogleda, in glej, grm gori v ognju, pa grm ne zgori.',
        3: 'In reče Mojzes: Stopim vendar tja in pogledam to veliko prikazen, zakaj grm ne zgori?',
        4: 'Ko pa vidi Gospod, da stopa bliže, da bi pogledal, mu zakliče Bog iz sredi grma in veli: Mojzes, Mojzes! On pa reče: Tukaj sem.',
        5: 'In veli: Ne bližaj se semkaj! Sezuj obuvalo z nog svojih, zakaj mesto, ki na njem stojiš, je sveta zemlja.',
        6: 'In reče: Jaz sem Bog očeta tvojega, Bog Abrahamov, Bog Izakov in Bog Jakobov. In Mojzes si zastre obraz, kajti boji se ozreti v Boga.',
        7: 'In Gospod reče: Videl sem, videl stisko ljudstva svojega, ki je v Egiptu, in njih vpitje pred njih priganjači sem slišal, kajti jaz poznam bolečine njegove.',
        8: 'In stopil sem doli, da ga otmem iz rok Egipčanov in odpeljem iz one dežele v dobro in prostrano deželo, v deželo, v kateri teče mleko in med, v kraj Kanaancev in Hetejcev in Amorejcev in Ferizejcev in Hevejcev in Jebusejcev.',
        9: 'In sedaj, glej, vpitje sinov Izraelovih je prišlo do mene, in videl sem tudi stisko, s katero jih stiskajo Egipčani.',
        10: 'Sedaj torej pojdi, da te pošljem k Faraonu, in popelji moje ljudstvo, sinove Izraelove, iz Egipta.',
        11: 'In reče Mojzes Bogu: Kdo sem jaz, da naj grem k Faraonu ter popeljem sinove Izraelove iz Egipta?',
        12: 'On pa reče: Jaz bodem s teboj, in to ti bodi znamenje, da sem te jaz poslal: ko popelješ ljudstvo iz Egipta, boste služili Bogu na tejle gori.',
        13: 'In Mojzes odgovori Bogu: Glej, ko pridem k sinovom Izraelovim in jim porečem: Bog očetov vaših me je poslal k vam, in mi oni reko: Katero je ime njegovo? kaj naj jim povem?',
        14: 'In Bog reče Mojzesu: JAZ SEM, KI SEM. In reče: Tako boš rekel sinovom Izraelovim: JAZ SEM me je poslal k vam.',
        15: 'In Bog reče dalje Mojzesu: Tako reci sinovom Izraelovim: Gospod, Bog očetov vaših, Bog Abrahamov, Bog Izakov in Bog Jakobov, me je poslal k vam. To je moje ime vekomaj in to je spomin moj od roda do roda.',
        16: 'Pojdi in zberi starejšine Izraelove in jih govóri: Gospod, Bog očetov vaših, se mi je prikazal, Bog Abrahamov, Izakov in Jakobov, govoreč: Zares sem vas obiskal in videl, kako se vam godi v Egiptu,',
        17: 'in rekel sem: Izvesti vas hočem iz stiske egiptovske v deželo Kanaancev in Hetejcev in Amorejcev in Ferizejcev in Hevejcev in Jebusejcev, v deželo, v kateri teče mleko in med.',
        18: 'In poslušali bodo tvoj glas. Potem pojdeš ti in starejšine izraelski h kralju egiptovskemu in mu porečete: Gospod, Bog Hebrejcev, nam je prišel naproti. In sedaj dovoli, da gremo tri dni hoda v puščavo in darujemo Gospodu, Bogu svojemu.',
        19: 'Pa jaz vem, da vam kralj egiptovski ne dovoli, da bi šli, tudi ne, če z mogočno roko pridem nadenj.',
        20: 'In iztegnem roko svojo in udarim Egipt z vsemi čudovitimi deli svojimi, katera bom storil sredi njega; in potem vas izpusti.',
        21: 'In dam milost temu ljudstvu v očeh Egipčanov, in zgodi se, ko izidete, ne pojdete prazni:',
        22: 'marveč vsaka žena bo izprosila od sosede in domačinke svoje srebrnih in zlatih dragotin ter oblačil, in naložite jih sinovom in hčeram svojim in oplenite Egipčane.',
    },
    4: {
        1: 'Mojzes pa odgovori in reče: Glej, pa oni mi ne bodo verovali in ne bodo poslušali glasu mojega, ampak porečejo: Ni se ti prikazal Gospod.',
        2: 'In Gospod mu reče: Kaj je to v tvoji roki? Odgovori: Palica.',
        3: 'In veli: Vrzi jo na tla! In vrže jo na tla, in postala je kača, in Mojzes zbeži pred njo.',
        4: 'In Gospod reče Mojzesu: Iztegni roko in primi jo za rep. In iztegne roko in jo zgrabi, in bila je palica v roki njegovi –:',
        5: 'da bi verovali, da se ti je prikazal Gospod, Bog njih očetov, Bog Abrahamov, Bog Izakov in Bog Jakobov.',
        6: 'Še mu veli Gospod: Vtakni roko v nedrije svoje! In vtakne roko v nedrije svoje, in ko jo iztegne, glej, roka njegova je gobava in bela kakor sneg.',
        7: 'In veli: Vtakni zopet roko v nedrije svoje! In vtakne zopet roko v nedrije, in ko jo iztegne izza nedrija, glej, je zopet kakor vse meso njegovo.',
        8: 'In zgodi se, če ti ne bodo verovali ter ne poslušali glasu prvega znamenja, bodo pa verovali v glas drugega znamenja.',
        9: 'In če ne bodo verovali tudi tema dvema znamenjema in ne bodo poslušali glasu tvojega, tedaj vzameš vode iz reke in jo izliješ na suho; in izpremeni se voda, ki jo vzameš iz reke, v kri na suhem.',
        10: 'In Mojzes reče Gospodu: Prosim, Gospod, jaz nisem zgovoren mož, niti nisem bil kdaj poprej, niti odkar si izpregovoril s hlapcem svojim; kajti imam okorna usta in težek jezik.',
        11: 'In Gospod mu reče: Kdo je naredil usta človeku? in kdo stori koga nemega ali gluhega ali videčega ali slepega? ali ne jaz, Gospod?',
        12: 'In sedaj pojdi, in jaz bodem pri tvojih ustih in te naučim, kaj naj govoriš.',
        13: 'On pa reče: Prosim, Gospod, pošlji vendar onega, ki ga hočeš poslati.',
        14: 'In vname se srd Gospodov zoper Mojzesa, in reče: Ali nimaš brata Arona, ki je levit? Vem, da je on jako zgovoren. Pa glej, gre ti tudi že naproti, in ko te zagleda, se razveseli v srcu svojem.',
        15: 'Ti pa govóri k njemu in položi besede moje v usta njegova, in jaz bodem pri ustih tvojih in pri ustih njegovih, in učil vaju bom, kaj naj storita.',
        16: 'On naj govori ljudstvu namesto tebe; in zgodi se, da bode on tebi za usta in ti bodeš njemu kakor Bog.',
        17: 'In v roko svojo vzemi to palico, ki boš ž njo storil ona znamenja.',
        18: 'In Mojzes odide in se vrne k Jetru, svojemu tastu, in mu reče: Daj, da grem in se povrnem k bratom svojim, ki so v Egiptu, in pogledam, če so še živi. In Jetro reče Mojzesu: Pojdi v miru!',
        19: 'In rekel je Gospod Mojzesu v Madianu: Pojdi, povrni se v Egipt, kajti pomrli so vsi ljudje, ki so ti stregli po življenju.',
        20: 'Mojzes vzame torej ženo svojo in sinova svoja in jih posadi na osla in se napoti nazaj v deželo Egiptovsko. Vzame tudi palico Božjo v roko svojo.',
        21: 'In Gospod je govoril Mojzesu: Ker torej greš, da se povrneš v Egipt, pazi, da storiš pred Faraonom vse čudeže, ki sem jih položil v roko tvojo. Jaz pa otrdim srce njegovo, da ne bo hotel odpustiti ljudstva.',
        22: 'In govoril boš Faraonu: Tako pravi Gospod: Izrael je sin moj, prvenec moj.',
        23: 'In velel sem ti, da odpustiš sina mojega, da mi služi; a ker si se branil ga pustiti, glej, umorim sina tvojega, prvenca tvojega.',
        24: 'In zgodi se na potu, v prenočišču, da mu pride Gospod naproti, in hotel ga je usmrtiti.',
        25: 'In vzame Zifora oster kamen in obreže kožico sinu svojemu in jo vrže Mojzesu k nogam, rekoč: Ker si mi ženin krvi.',
        26: 'In prizanesel mu je Gospod. Tedaj reče ona: Ženin krvi si, zaradi obreze.',
        27: 'In rekel je bil Gospod Aronu: Pojdi v puščavo Mojzesu naproti! In on odide, in sreča ga na gori Božji in ga poljubi.',
        28: 'In Mojzes sporoči Aronu vse besede Gospodove, s katerimi ga je poslal, in vsa znamenja, ki mu jih je ukazal.',
        29: 'Prideta torej Mojzes in Aron ter skličeta vse starejšine sinov Izraelovih.',
        30: 'In pripovedoval je Aron vse besede, ki jih je bil Gospod govoril Mojzesu, in delal je znamenja vpričo ljudstva.',
        31: 'In ljudstvo je verovalo. In ko so slišali, da je Gospod obiskal sinove Izraelove in da se je ozrl na njih bedo, so se priklonili in molili Gospoda.',
    },
    5: {
        1: 'In potem sta šla Mojzes in Aron ter rekla Faraonu: Tako pravi Gospod, Bog Izraelov: Pusti ljudstvo moje, da mi obhajajo praznik v puščavi.',
        2: 'In Faraon odgovori: Kdo je Gospod, čigar glas naj poslušam, da izpustim Izraela? Ne poznam Gospoda, tudi Izraela ne bom pustil.',
        3: 'In ona rečeta: Bog Hebrejcev nam je prišel naproti. Pústi nas, prosimo, da gremo tri dni hoda v puščavo in darujemo Gospodu, Bogu svojemu, da nas ne kaznuje s kugo ali z mečem.',
        4: 'In kralj egiptovski jima reče: Zakaj hočeta, Mojzes in Aron, oprostiti ljudstvo dela njegovega? Pojdita le k raboti svoji!',
        5: 'In Faraon reče: Glejta, preveč je že ljudstva v deželi, in vidva mu hočeta dati počitek od rabote njegove!',
        6: 'In ukazal je Faraon tistega dne priganjačem ljudstva in nadzornikom njegovim, rekoč:',
        7: 'Ne smete več ljudstvu dajati slame za izdelovanje opeke kakor doslej; naj sami gredo in si naberejo slame.',
        8: 'Toda isto število opeke, kolikor so jo izdelovali doslej, jim morate naložiti, ne odštevši prav ničesar; kajti nič ne delajo, zato vpijejo, govoreč: Pojdimo darovat Bogu svojemu!',
        9: 'Težavna bodi služba tem ljudem, da bodo imeli dosti opravila in ne bodo pazili na lažnive besede!',
        10: 'In odšli so priganjači ljudstva in njegovi nadzorniki in govorili so ljudstvu: Tako pravi Faraon: Slame vam ne bom več dajal.',
        11: 'Pojdite sami, prinesite si slame, kjerkoli je kaj najdete; toda služba se vam nič ne olajša.',
        12: 'In razkropilo se je ljudstvo po vsej zemlji Egiptovski, da bi zbirali strn za slamo.',
        13: 'Priganjači pa so jih pritiskali, govoreč: Opravljajte svoje delo, vsak dan svoje delo, kakor takrat, ko je bila slama.',
        14: 'In bili so tepeni nadzorniki sinov Izraelovih, ki so jih nad njimi postavili priganjači Faraonovi; rekli so jim: Zakaj niste dodelali svojega števila opeke, ne včeraj, ne danes, kakor ste poprej?',
        15: 'In prišli so nadzorniki sinov Izraelovih k Faraonu in so vpili in rekli: Zakaj tako ravnaš s hlapci svojimi?',
        16: 'Slame ne dajó hlapcem tvojim, vendar velevajo: Delajte opeko; in glej, hlapci tvoji so tepeni, in krivo je tvoje ljudstvo.',
        17: 'On pa reče: Nič ne delate, nič ne delate! zato govorite: Pojdimo darovat Gospodu!',
        18: 'In zdaj pojdite in delajte! Slame vam ne bodo dajali, a število opeke morate oddati.',
        19: 'In izprevideli so nadzorniki sinov Izraelovih, da so v stiski, ker morajo reči: Nič manj ne delajte opeke; vsak dan svoje delo!',
        20: 'Ko so se torej sešli z Mojzesom in Aronom, ki sta stala, da bi jih srečala na poti od Faraona,',
        21: 'so jima rekli: Gospod poglej na vaju in naj sodi, ker sta naš duh smrdljiv storila pred Faraonom in pred služabniki njegovimi, da bi dala meč v njih roke, da nas pomoré.',
        22: 'In obrne se Mojzes h Gospodu in reče: Gospod, zakaj ravnaš tako hudo s tem ljudstvom? zakaj si me vendar poslal?',
        23: 'Kajti odkar sem šel k Faraonu, da bi govoril v tvojem imenu, ravna še huje s tem ljudstvom, in ti nisi nikakor rešil ljudstva svojega.',
    },
    6: {
        1: 'In Gospod reče Mojzesu: Sedaj boš videl, kaj storim Faraonu: kajti z mogočno roko storim, da jih odpošlje, in z mogočno roko, da jih izžene iz dežele svoje.',
        2: 'In govoril je Bog Mojzesu in mu rekel: Jaz sem Jehova.',
        3: 'In pokazal sem se Abrahamu, Izaku in Jakobu Bog silni, Vsegamogočni, ali po imenu svojem Jehova se jim nisem razodel.',
        4: 'Tudi zavezo svojo sem ustanovil ž njimi, da jim dam deželo Kanaansko, deželo njih popotovanja, ki so živeli v njej kot tujci.',
        5: 'Čul sem tudi stokanje sinov Izraelovih, ki jih Egipčani silijo k službi, in spomnil sem se zaveze svoje.',
        6: 'Zatorej govóri sinovom Izraelovim: Jaz sem Jehova; jaz vas hočem odpeljati izpod tlake Egipčanom in vas iztrgati iz njih službe in vas rešiti z iztegnjeno roko in z velikimi sodbami;',
        7: 'in sprejeti vas hočem za svoje ljudstvo, in bodem vam Bog, in spoznali boste, da sem jaz Jehova, Bog vaš, ki sem vas odpeljal izpod tlake Egipčanom;',
        8: 'in privesti vas hočem v deželo, za katero sem povzdignil svojo roko in prisegel, da jo dam Abrahamu, Izaku in Jakobu, in hočem vam jo dati v posest, jaz, Jehova.',
        9: 'In govoril je Mojzes tako sinovom Izraelovim, a oni ga vsled bridkosti duha in vsled trde sužnosti niso poslušali.',
        10: 'In govoril je Gospod Mojzesu, rekoč:',
        11: 'Pojdi noter, govóri Faraonu, kralju egiptovskemu, da odpusti sinove Izraelove iz dežele svoje.',
        12: 'In Mojzes je pred Gospodom govoril, rekoč: Glej, sinovi Izraelovi me niso poslušali, kako me bode pač poslušal Faraon, ker sem okornega jezika?',
        13: 'In Gospod je govoril Mojzesu in Aronu in jima dal zapoved za sinove Izraelove in za Faraona, kralja egiptovskega, da bi sinovi Izraelovi šli iz dežele Egiptovske.',
        14: 'To so prvaki očetovskih hiš svojih: Sinovi Rubena, prvenca Izraelovega: Hanok, Palu, Hezron in Karmi; to so rodovine Rubenove.',
        15: 'In sinovi Simeonovi: Jemuel, Jamin, Ohad, Jakin, Zohar in Savel, sin Kanaanke; to so rodovine Simeonove.',
        16: 'In ta so imena sinov Levijevih po svojih rodovih: Gerson, Kahat in Merari; in let življenja Levijevega je bilo sto sedemintrideset let.',
        17: 'Sinova Gersonova: Libni in Simej, po svojih rodovinah.',
        18: 'In sinovi Kahatovi: Amram in Izhar, Hebron in Uziel; in let življenja Kahatovega je bilo sto in triintrideset let.',
        19: 'In sinova Merarijeva: Mahli in Musi; to so rodovine Levijeve po svojih rodovih.',
        20: 'In vzel si je Amram Jokebedo, teto svojo, za ženo; in porodila mu je Arona in Mojzesa; in bilo je let življenja Amramovega sto in sedemintrideset let.',
        21: 'In sinovi Izharjevi: Korah, Nefeg in Zikri.',
        22: 'In sinovi Uzielovi: Misael, Elzafan in Sitri.',
        23: 'In vzel si je Aron Elisebo, hčer Aminadabovo, sestro Nahsonovo, za ženo; in porodila mu je Nadaba, Abihuja, Eleazarja in Itamarja.',
        24: 'In sinovi Korahovi: Asir, Elkana in Abiasaf; to so rodbine Korahovcev.',
        25: 'In Eleazar, sin Aronov, si je vzel eno izmed hčera Putielovih za ženo; in porodila mu je Pinehasa. To so prvaki, očetje levitov po svojih rodovinah.',
        26: 'To sta Aron in Mojzes, ki jima je rekel Gospod: Izpeljita sinove Izraelove iz dežele Egiptovske po njih vojnih krdelih.',
        27: 'Ona sta, ki sta govorila Faraonu, kralju egiptovskemu, zaradi odhoda sinov Izraelovih iz Egipta: ta Mojzes in Aron.',
        28: 'In zgodilo se je tisti dan, ko je govoril Gospod Mojzesu v deželi Egiptovski,',
        29: 'da je velel Gospod Mojzesu takole: Jaz sem Gospod; govóri Faraonu, kralju egiptovskemu, vse, kar jaz tebi govorim.',
        30: 'In Mojzes reče pred Gospodom: Glej, jaz sem okornega jezika, in kako naj bi me poslušal Faraon?',
    },
    7: {
        1: 'In Gospod reče Mojzesu: Poglej, postavljam te za boga Faraonu, in Aron, brat tvoj, bode tvoj prorok.',
        2: 'Ti boš govoril vse, kar ti ukažem, in Aron, brat tvoj, bo govoril Faraonu, da pusti sinove Izraelove iz dežele svoje.',
        3: 'Jaz pa zakrknem srce Faraonu in pomnožim znamenja svoja in čudeže svoje v deželi Egiptovski.',
        4: 'In Faraon vas ne bo poslušal; in položim roko svojo na Egipt in izvedem svoje vojske, svoje ljudstvo, sinove Izraelove, iz Egiptovske dežele z velikimi sodbami.',
        5: 'In spoznali bodo Egipčani, da sem jaz Gospod, ko iztegnem roko svojo nad Egiptom in izpeljem sinove Izraelove izmed njih.',
        6: 'Mojzes in Aron sta torej storila tako; kakor jima je ukazal Gospod, tako sta storila.',
        7: 'In Mojzes je bil osemdeset let star, Aron pa triinosemdeset let, ko sta govorila Faraonu.',
        8: 'In govoril je Gospod Mojzesu in Aronu, rekoč:',
        9: 'Ko bo z vama govoril Faraon in rekel: Naredita za sebe kak čudež! tedaj véli Aronu: Vzemi palico svojo in vrzi jo na tla pred Faraonom; postane naj velika kača!',
        10: 'In gresta Mojzes in Aron k Faraonu in storita, kakor je ukazal Gospod: Aron je namreč vrgel palico svojo na tla pred Faraonom in pred služabniki njegovimi, in postala je velika kača.',
        11: 'Tedaj pokliče tudi Faraon modrijane in čarodeje; in napravili so tudi oni, pismouki egiptovski, enako s čarovništvom svojim:',
        12: 'vsak je vrgel palico svojo na tla, in postale so velike kače; a Aronova palica je požrla njih palice.',
        13: 'Ali srce Faraonovo se je otrdilo, in ni ju poslušal, kakor je bil govoril Gospod.',
        14: 'In reče Gospod Mojzesu: Srce Faraonovo je trdo; brani se izpustiti ljudstvo.',
        15: 'Idi k Faraonu zjutraj, glej, pojde ven k vodi; in stopi mu naproti ob bregu Nilovem, in palico, ki se je izpremenila v kačo, vzemi v roko svojo',
        16: 'in govori k njemu: Gospod, Bog Hebrejcev, me je poslal k tebi s tem naročilom: Odpusti ljudstvo moje, da mi služi v puščavi; in glej, dozdaj nisi poslušal.',
        17: 'Tako pravi Gospod: Po tem spoznaš, da sem jaz Gospod: glej, udarim s palico, ki je v roki moji, po vodi, ki je v reki, in izpremenila se bo v kri.',
        18: 'Ribe pa, ki so v reki, poginejo, in reka se usmradi, in gnusilo se bo Egipčanom piti vodo iz reke.',
        19: 'In reče Gospod Mojzesu: Véli Aronu: Vzemi palico svojo in iztegni roko svojo nad vodami v Egiptu, nad njegovimi rekami, nad njegovimi vodotoki, nad njegovimi ribniki in nad vsemi vodnjaki njegovimi, da postanejo kri; in kri bode po vsej deželi Egiptovski, i v lesenih i v kamenitih posodah.',
        20: 'In storila sta tako Mojzes in Aron, kakor je bil ukazal Gospod: povzdignil je palico in je udaril po vodi v reki, pred očmi Faraonovimi in pred očmi služabnikov njegovih; in vsa voda, kar je je bilo v reki, se je izpremenila v kri.',
        21: 'In ribe, ki so bile v reki, so poginile, in reka se je usmradila, in Egipčani niso mogli piti vode iz reke; in bila je kri po vsej deželi Egiptovski.',
        22: 'A pismouki egiptovski so naredili enako s čarovništvom svojim. In srce Faraonovo se je otrdilo in ni ju poslušal, kakor je bil govoril Gospod.',
        23: 'In obrnil se je Faraon in šel na svoj dom, in niti to mu ni seglo do srca.',
        24: 'In vsi Egipčani so kopali poleg reke, da dobe pitne vode, zakaj vode iz reke niso mogli piti.',
        25: 'In preteklo je celih sedem dni, odkar je Gospod udaril reko.',
    },
    8: {
        1: 'Tedaj reče Gospod Mojzesu: Idi k Faraonu in mu reci: Tako pravi Gospod: Izpusti moje ljudstvo, da mi služi!',
        2: 'Če se boš pa branil ga izpustiti, glej, udarim vse pokrajine tvoje z žabami.',
        3: 'In v reki bo kar mrgolelo žab, in izlezle bodo in šle v hišo tvojo in v spalnico in na posteljo tvojo, in v hiše služabnikov tvojih in med ljudstvo tvoje in v peči tvoje in v nečke tvoje;',
        4: 'tudi na tebe kakor na tvoje ljudstvo in na vse služabnike tvoje bodo prilezle žabe.',
        5: 'In Gospod reče Mojzesu: Véli Aronu: Iztegni roko s palico svojo nad rekami, nad vodotoki in nad ribniki in stóri, da pridejo žabe nad deželo Egiptovsko.',
        6: 'In iztegne Aron roko svojo nad vodami Egipta, in žabe so prilezle na dan in pokrile deželo Egiptovsko.',
        7: 'In storili so pismouki enako s čarovništvom svojim, in izpeljali so žabe nad zemljo Egiptovsko.',
        8: 'Tedaj pokliče Faraon Mojzesa in Arona in reče: Prosite Gospoda, da odpravi žabe od mene in ljudstva mojega, in odpustil bom ljudstvo, da daruje Gospodu.',
        9: 'In Mojzes reče Faraonu: Čast ti bodi pred menoj, da določiš, za kateri čas naj prosim zate in za služabnike tvoje in za ljudstvo tvoje, da se zatró žabe pri tebi in po hišah tvojih, samo v reki naj ostanejo.',
        10: 'On pa reče: Za jutri. In Mojzes odgovori: Bodi po tvoji besedi, zato da spoznaš, da ni nikogar, kakor je Gospod, naš Bog.',
        11: 'In zapustijo žabe tebe in hiše tvoje in služabnike tvoje in ljudstvo tvoje, samo v reki ostanejo.',
        12: 'In odideta Mojzes in Aron izpred Faraona; Mojzes pa je vpil h Gospodu zaradi žab, ki jih je bil poslal nad Faraona.',
        13: 'In storil je Gospod po besedi Mojzesovi, in poginile so žabe v hišah, v dvorih in na poljih.',
        14: 'In nagrabili so jih velike grmade, in smrdela je zemlja.',
        15: 'Ko je pa videl Faraon, da je prišla olajšava, je zakrknil svoje srce in ni ju poslušal kakor je bil govoril Gospod.',
        16: 'In Gospod reče Mojzesu: Véli Aronu: Iztegni palico svojo in udari prah zemlje, in postanejo iz njega komarji po vsej deželi Egiptovski.',
        17: 'In storila sta tako; Aron namreč iztegne roko s palico svojo in udari prah zemlje, in prišli so komarji na ljudi in na živino; iz vsega prahu zemlje so postali komarji po vsej deželi Egiptovski.',
        18: 'In pismouki so poskušali isto s čarovništvom svojim, da napravijo komarje, a niso mogli. In bili so komarji na ljudeh in na živini.',
        19: 'Pismouki so torej rekli Faraonu: Prst Božji je to! Ali Faraonovo srce se je otrdilo in ni ju slušal, kakor je bil govoril Gospod.',
        20: 'In Gospod reče Mojzesu: Vstani zjutraj zgodaj in stopi pred Faraona; glej, on pride ven k vodi, in mu reci: Tako pravi Gospod: Izpusti ljudstvo moje, da mi služi!',
        21: 'Sicer, če ne izpustiš ljudstva mojega, glej, pošljem nad tebe in nad služabnike tvoje in nad ljudstvo tvoje in v tvoje hiše pasje muhe; in hiše Egipčanov bodo polne pasjih muh, pa tudi zemlja, v kateri so.',
        22: 'In tisti dan izločim deželo Gosensko, ki v njej prebiva ljudstvo moje, da tam ne bode nič muh, zato da spoznaš, da sem jaz Gospod sredi zemlje.',
        23: 'In postavim znamenje rešitve med svojim ljudstvom in ljudstvom tvojim. Jutri se zgodi to znamenje.',
        24: 'In Gospod je storil tako; in prišla je množica pasjih muh v hišo Faraonovo in v hiše služabnikov njegovih in nad vso deželo Egiptovsko, in pasje muhe so pokvarile deželo.',
        25: 'Tedaj pokliče Faraon Mojzesa in Arona ter reče: Idite, darujte Bogu svojemu tu v deželi!',
        26: 'In Mojzes odgovori: Ni spodobno, da tako storimo: zakaj gnusobo Egipčanov bi darovali Gospodu, Bogu svojemu; če pa darujemo gnusobo Egipčanov pred njih očmi, ali nas ne bodo kamenali?',
        27: 'Tri dni hoda pojdemo v puščavo, da darujemo Gospodu, Bogu svojemu, kakor nam bo velel.',
        28: 'In Faraon reče: Pustim vas torej, da darujete Gospodu, Bogu svojemu, v puščavi, samo ne hodíte predaleč. Molite zame!',
        29: 'Mojzes pa reče: Glej, grem izpred tebe in prosil bom Gospoda; in jutri popuste pasje muhe Faraona in služabnike njegove in ljudstvo njegovo. Samo da nas Faraon nič več na vara, ne hoteč odpustiti ljudstva, da daruje Gospodu.',
        30: 'In šel je Mojzes ven od Faraona ter prosil Gospoda.',
        31: 'In Gospod je storil po besedi Mojzesovi, in odžene pasje muhe od Faraona, od služabnikov njegovih in od ljudstva njegovega: niti ena ni ostala.',
        32: 'Ali Faraon je zakrknil srce svoje tudi takrat in ni izpustil ljudstva.',
    },
    9: {
        1: 'Tedaj je govoril Gospod Mojzesu: Idi k Faraonu in mu govóri: Tako pravi Gospod, Bog Hebrejcev: Izpusti ljudstvo moje, da mi služijo.',
        2: 'Zakaj če se boš branil jih odpustiti in jih še dalje zadrževal,',
        3: 'glej, roka Gospoda bode nad tvojo živino, ki je na polju: nad konji, nad osli, nad velblodi, nad govedi in nad drobnico v jako hudi kugi.',
        4: 'In Gospod napravi razloček med živino Izraelcev in med živino Egipčanov, in od vsega blaga, kar je sinov Izraelovih, ne pogine nič.',
        5: 'In Gospod je določil rok, rekoč: Jutri napravi Gospod to v deželi.',
        6: 'In storil je Gospod to drugi dan: in vsa živina Egipčanov je poginila, a izmed živine sinov Izraelovih še ena glava ne.',
        7: 'Pošlje pa Faraon, in glej, niti ena glava ni poginila sinovom Izraelovim. In zakrknilo se je srce Faraonovo, in ljudstva ni izpustil.',
        8: 'Tedaj reče Gospod Mojzesu in Aronu: Vzemita si iz peči polne pesti pepela, in Mojzes naj ga iztrese proti nebu pred očmi Faraonovimi.',
        9: 'In bodi v prah nad vso deželo Egiptovsko, in ljudje in živali dobodo ugnide, ki se izrinejo z osepnicami, po vsej deželi Egiptovski.',
        10: 'Vzela sta torej pepela in se postavila pred Faraona, in Mojzes ga raztrese proti nebu; in nastalo je ugnidje, ki se je v osepnicah izrinilo po ljudeh in govedi.',
        11: 'In pismouki niso mogli stati pred Mojzesom zaradi ugnidja, kajti pismouki so je imeli kakor vsi Egipčani.',
        12: 'Gospod pa je otrdil srce Faraonovo in ni ju slušal, kakor je bil govoril Gospod Mojzesu.',
        13: 'In Gospod reče Mojzesu: Vstani zjutraj zgodaj in stopi pred Faraona ter mu reci: Tako pravi Gospod, Bog Hebrejcev: Izpusti ljudstvo moje, da mi služi!',
        14: 'Kajti to pot pošljem vse šibe svoje nad tvoje srce in nad služabnike tvoje in nad ljudstvo tvoje, zato da spoznaš, da nikogar ni meni enakega na vsej zemlji.',
        15: 'Kajti zdaj sem že iztegnil roko svojo, in ko bi bil s kugo udaril tebe in ljudstvo tvoje, bi bil iztrebljen z zemlje.',
        16: 'Ali zaradi tega sem te ohranil, da ti pokažem svojo moč ter da se razglasi ime moje po vsej zemlji.',
        17: 'Ako se še vzpenjaš zoper moje ljudstvo, ne hoteč ga izpustiti:',
        18: 'glej, jutri obsore storim, da bo padala debela toča, kakršne še ni bilo v Egiptu od dne, ko je bil postavljen, do sedaj.',
        19: 'Zdaj pa pošlji in spravi v zavetje živino svojo in karkoli imaš na polju; zakaj vsak človek in vsaka žival, ki bode na polju in se ne shrani v hiši, pogine, ko se usuje toča.',
        20: 'Kdorkoli izmed služabnikov Faraonovih se je bal besede Gospodove, je spravil svoje hlapce in živino svojo na varno v hiše.',
        21: 'Kdor si pa ni vzel besede Gospodove k srcu, je pustil svoje hlapce in živino na polju.',
        22: 'In Gospod reče Mojzesu: Iztegni roko proti nebu, da pride toča nad vso deželo Egiptovsko, nad ljudi in nad živali in nad vso poljsko zelenjavo v deželi Egiptovski.',
        23: 'In Mojzes je iztegnil palico svojo proti nebu, in Gospod je dal grom in točo, in ogenj je švigal na zemljo, in Gospod je dežil točo na deželo Egiptovsko.',
        24: 'In padala je toča in ogenj je neprestano švigal med točo, jako hudo, kakršne ni bilo v vsej deželi Egiptovski, odkar je last naroda.',
        25: 'In potolkla je toča po vsej deželi Egiptovski, karkoli je bilo na polju, od človeka do živine, in vso zelenjavo na polju je potolkla toča in polomila sleherno drevo na polju.',
        26: 'Samo v deželi Gosenski, kjer so bili sinovi Izraelovi, ni bilo toče.',
        27: 'In pošlje Faraon ter pokliče Mojzesa in Arona in jima reče: Pregrešil sem se ta krat. Gospod je pravičen, jaz pa in ljudstvo moje smo krivičniki.',
        28: 'Prosite Gospoda, in dovolj bodi groma Božjega in toče, in izpustim vas, in ne ostanete več tukaj.',
        29: 'In odgovori mu Mojzes: Ko pridem iz mesta, razprostrem roke svoje proti Gospodu: grmenje poneha in toče ne bode več, zato da spoznaš, da je zemlja Gospodova.',
        30: 'Vem pa, da se ti in služabniki tvoji še ne bojite Gospoda Boga. –',
        31: 'In lan in ječmen sta bila pokončana: kajti ječmen je bil že v klasju in lan je poganjal glavice.',
        32: 'Pšenica pa in pira nista bili pokončani, ker sta pozni. –',
        33: 'In ko pride Mojzes od Faraona ven iz mesta, razprostre roke proti Gospodu, in nehalo je grmeti, tudi dež ni več lil na zemljo.',
        34: 'Ko je pa Faraon videl, da je konec dežju, toči in grmenju, je grešil nadalje, in zakrknil je srce svoje on in služabniki njegovi.',
        35: 'In otrdilo se je srce Faraonovo, in ni izpustil sinov Izraelovih, kakor je bil govoril Gospod po Mojzesu.',
    },
    10: {
        1: 'In Gospod reče Mojzesu: Idi k Faraonu; kajti zakrknil sem srce njegovo in srce hlapcev njegovih zato, da bi napravil ta znamenja svoja med njimi,',
        2: 'in zato, da bi ti pripovedoval ušesom sinov svojih in otrok sinov svojih, kar sem izvršil v Egiptu, in o znamenjih mojih, ki sem jih naredil med njimi; da boste spoznali, da sem jaz Gospod.',
        3: 'In odideta Mojzes in Aron k Faraonu ter mu rečeta: Tako pravi Gospod, Bog Hebrejcev: Doklej se boš ustavljal ponižati se pred menoj? Izpusti ljudstvo moje, da mi služi!',
        4: 'Sicer ako se boš branil odpustiti ljudstvo moje, glej, jutri pošljem kobilice v pokrajine tvoje.',
        5: 'In pokrijejo površje zemlje, da je ne boste nič videli; in pojedle bodo ostanek, kar se je ohranilo in kar vam je preostalo po toči, in oglodale bodo vsa drevesa, ki vam rasto na polju;',
        6: 'in napolnijo hiše tvoje in hiše vseh služabnikov tvojih in hiše vseh Egipčanov, kolikor jih niso videli očetje tvoji in dedje, odkar so na zemlji do današnjega dne. In obrne se in odide od Faraona.',
        7: 'Tedaj reko Faraonu hlapci njegovi: Doklej nam bode ta mož za zanko? Odpusti tiste ljudi, da služijo Gospodu, svojemu Bogu! Ali mar še ne veš, da je Egipt pri koncu?',
        8: 'In pokličejo nazaj Mojzesa in Arona k Faraonu, in on jima reče: Pojdite, služite Gospodu, Bogu svojemu! Kateri pa so tisti, ki naj gredo?',
        9: 'In Mojzes odgovori: S svojo mladino in s svojimi starci pojdemo; s sinovi in hčerami svojimi, z drobnico in govedjo svojo odidemo; ker imamo praznik Gospodov.',
        10: 'In on jima reče: Bodi tako Gospod z vami, kakor jaz odpuščam vas in otročiče vaše! Glejte, da imate v mislih kaj hudega!',
        11: 'Ne tako! Pojdite le vi možje, in služite Gospodu; zakaj to je, kar ste želeli. In izgnali so ju izpred obličja Faraonovega.',
        12: 'Tedaj reče Gospod Mojzesu: Iztegni roko svojo nad deželo Egiptovsko zaradi kobilic, da pridejo nad Egiptovsko deželo in požro vsa zelišča na zemlji, vse, kar je preostalo po toči.',
        13: 'In Mojzes iztegne palico svojo nad deželo Egiptovsko, in Gospod zažene vzhodni veter v deželo ves tisti dan in vso noč; in ko se je zdanilo, prinese vzhodni veter kobilice.',
        14: 'In prišle so kobilice nad vso Egiptovsko deželo in posedle so vse kraje Egipta v silno veliki množici; nikdar poprej ni bilo takšnih kobilic, tudi pozneje ne bo takih.',
        15: 'Kajti pokrile so površje vse dežele, tako da se je stemnila dežela, in požrle so vsa zelišča na zemlji in vse sadje po drevju, kar je bilo preostalo po toči; in nič zelenega ni ostalo, ne drevja, ne zelišč na polju, po vsej deželi Egiptovski.',
        16: 'Tedaj pokliče Faraon hitro Mojzesa in Arona in reče: Grešil sem zoper Gospoda, vašega Boga, in zoper vas.',
        17: 'Sedaj pa odpusti, prosim, greh moj, samo še zdaj, in prosita Gospoda, vašega Boga, da odvrne od mene vsaj to smrt.',
        18: 'In Mojzes odide od Faraona ter prosi Gospoda.',
        19: 'In Gospod stori, da potegne zahodni veter, jako silen, ki je vzdignil kobilice in jih zagnal v Rdeče morje. Ne ene kobilice ni ostalo v vseh krajih Egipta.',
        20: 'Gospod pa je otrdil srce Faraonovo, da ni odpustil sinov Izraelovih.',
        21: 'In reče Gospod Mojzesu: Iztegnil roko proti nebu, in nastane tema nad Egiptovsko deželo, tema, da jo bodo kar tipali.',
        22: 'In Mojzes iztegne roko proti nebu, in bila je gosta tema po vsej deželi Egiptovski tri dni.',
        23: 'Niso videli drug drugega, nihče tudi ni vstal s svojega mesta v teh treh dnevih; a vsi sinovi Izraelovi so imeli svetlo v prebivališčih svojih.',
        24: 'In pokliče Faraon Mojzesa in reče: Idite, služite Gospodu; samo vaše ovce in vaši voli naj ostanejo tu, tudi otroci vaši naj gredo z vami.',
        25: 'Mojzes pa odgovori: Tudi klalne in žgalne daritve moraš dati v roke naše, da jih pripravimo Gospodu, Bogu svojemu.',
        26: 'Tudi živina naša pojde z nami, tu ne sme ostati niti en parkelj, ker od nje vzamemo, s čimer bomo služili Gospodu, Bogu svojemu; kajti mi ne vemo, s čim naj služimo Gospodu, dokler ne pridemo tjakaj.',
        27: 'Ali Gospod je otrdil srce Faraonovo, da jih ni hotel izpustiti.',
        28: 'In Faraon mu reče: Pojdi izpred mene! Varuj se, da ne vidiš več obličja mojega, zakaj v dan, kadar bi zagledal obličje moje, umrješ.',
        29: 'In Mojzes reče: Prav si povedal: nikoli več ne bom videl obličja tvojega.',
    },
    11: {
        1: 'Govoril pa je bil Gospod Mojzesu: Še eno šibo pošljem nad Faraona in nad Egipt, potem vas izpusti odtod; ko vas res izpusti, vas še celo izžene odtod.',
        2: 'Govori zdaj na ušesa ljudstvu, naj prosi vsakdo od svojega soseda in vsaka od sosede svoje srebrnih in zlatih dragotin.',
        3: 'In dal je Gospod ljudstvu milost v očeh Egipčanov. Tudi Mojzes je bil jako imeniten mož v deželi Egiptovski, v očeh služabnikov Faraonovih in v očeh ljudstva.',
        4: 'In Mojzes reče: Tako pravi Gospod: Opolnoči pojdem sredi Egipta;',
        5: 'in umrjo vsi prvorojenci v Egiptovski deželi, od prvenca Faraonovega, ki bi mu bilo sedeti na njegovem prestolu, do prvenca dekle pri ročnem mlinu in vsa prvenščina živali.',
        6: 'In bo veliko vpitje po vsej deželi Egiptovski, kakršnega nikoli ni bilo in ga nikdar več ne bode.',
        7: 'A pri vseh sinovih Izraelovih niti pes ne migne z jezikom svojim, ne proti ljudem, ne proti živini, zato da izprevidite, da Gospod dela razloček med Egipčani in med Izraelom.',
        8: 'In pridejo k meni doli vsi ti služabniki tvoji ter, priklanjajoč se mi, poreko: Izidi ti in vse ljudstvo, ki ti sledi; in potem izidem. In odšel je izpred Faraona v goreči jezi.',
        9: 'In Gospod je rekel Mojzesu: Faraon vaju ne posluša, zato da se pomnožé čudeži moji v Egiptovski deželi.',
        10: 'In Mojzes in Aron sta storila vse te čudeže pred Faraonom; a Gospod je otrdil srce Faraonovo, in on ni odpustil sinov Izraelovih iz dežele svoje.',
    },
    12: {
        1: 'In Gospod je govoril Mojzesu in Aronu v deželi Egiptovski, rekoč:',
        2: 'Ta mesec vam bodi začetek mesecev, ta vam bodi prvi med meseci v letu.',
        3: 'Govorita vsemu zboru Izraelovemu, rekoč: Deseti dan tega meseca naj si priskrbi vsakdo jagnje za rodbinsko hišo, eno jagnje za hišo.',
        4: 'Če je pa hiša premajhna za eno jagnje, naj ga vzame on in njegov sosed, najbližji hiši njegovi, po številu duš; vsakterega štejte po tem, kolikor jé, na jagnje.',
        5: 'Jagnje bodi brez madeža, samec, leto staro; vzemite ga izmed ovac ali pa izmed koz.',
        6: 'In hranili ga boste do štirinajstega dne tega meseca, in zakolje ga ves zbor občine Izraelove proti večeru.',
        7: 'In vzamejo naj krvi in pomažejo ž njo oba podboja in naddurje pri hišah, v katerih ga bodo jedli.',
        8: 'In jedli bodo meso njegovo tisto noč, pečeno na ognju, in opresne kruhe; z grenkimi zelišči naj ga jedo.',
        9: 'Ne smete jesti ničesar od njega sirovega, tudi ne v vodi kuhanega, temuč pečeno na ognju: glavo njegovo z njegovimi nogami in z njegovim drobom vred.',
        10: 'In ne pustite, da bi od njega kaj ostalo do jutra; če pa preostane kaj do jutra, sežgite na ognju.',
        11: 'Takole ga pa boste jedli: Ledja imejte opasana, opanke svoje na nogah in palico v roki; in jedli ga boste, kakor da proč hitite. Gospodova je pasha.',
        12: 'Zakaj to noč pojdem skozi deželo Egiptovsko, in udarim vso prvenščino v deželi Egiptovski, od človeka do živali, in nad vsemi bogovi egiptovskimi napravim sodbo, jaz, Gospod.',
        13: 'In ona kri vam bodi v znamenje na hišah, v katerih bodete: in ko zagledam kri, pojdem mimo vas, in ne pride nad vas šiba, vam v pogubljenje, kadar udarim deželo Egipt.',
        14: 'In ta dan vam bodi za spomin, in praznovali ga boste v praznik Gospodu; kot večno postavo v svojih prihodnjih rodovih ga praznujte.',
        15: 'Sedem dni boste jedli opresne kruhe; takoj prvi dan odstranite kvas iz hiš svojih: zakaj kdorkoli bi jedel kaj kvašenega od prvega do sedmega dne, ta duša bo iztrebljena iz Izraela.',
        16: 'In prvega dne imejte sveto zborovanje, tudi sedmega dne sveto zborovanje; nobenega dela ne boste ta čas opravljali, samo kar je treba vsakemu za živež, pripravite.',
        17: 'Spoštujte torej praznik opresnikov, zakaj ravno tisti dan sem odpeljal trume vaše iz dežele Egiptovske; hranite torej ta dan v prihodnjih rodovih svojih kot večno postavo.',
        18: 'Štirinajsti dan prvega meseca zvečer boste jedli opresnike do edenindvajsetega dne istega meseca zvečer.',
        19: 'Sedem dni ne bodi kvasu v hišah vaših, zakaj kdorkoli jé kaj kvašenega, iztrebljena bode duša njegova iz Izraelove občine, bodisi tujec ali rojen v deželi.',
        20: 'Nič kvašenega ne boste jedli, v vseh prebivališčih svojih jejte kruhe opresne.',
        21: 'In pokliče Mojzes vse starejšine Izraelove in jim reče: Izberite in vzemite zase drobnico, po rodbinah svojih, in zakoljite pasho.',
        22: 'In vzemite šopek izopa in pomočite ga v kri, ki je v medenici, in pomažite naddurje in oba podboja s krvjo, ki je v medenici; a nihče izmed vas naj ne hodi ven skozi duri hiše svoje do jutra.',
        23: 'Gospod namreč pojde skozi Egipt, da udari Egipčane; ko bo pa videl kri na naddurju in na obeh podbojih, pojde Gospod mimo hišnih duri ter ne dopusti, da bi šel morilec v hiše vaše vas pogubljat.',
        24: 'Izpolnjujte torej to kot postavo zase in za otroke svoje vekomaj.',
        25: 'In ko pridete v deželo, ki vam jo da Gospod, kakor je bil obljubil, izpolnjujte to službo.',
        26: 'In kadar vam poreko vaši otroci: Kaj vam pomeni ta služba?',
        27: 'odgovorite: Daritev pashe je to Gospodu, ki je šel mimo hiš Izraelovih sinov v Egiptu, ko je tepel Egipčane, in naše hiše je otel. In ljudstvo se je priklonilo in molilo Boga.',
        28: 'In sinovi Izraelovi so šli in storili tako; kakor je bil Gospod ukazal Mojzesu in Aronu, tako so storili.',
        29: 'In zgodilo se je opolnoči, da je Gospod udaril vse prvorojeno v Egiptovski deželi, od prvenca Faraonovega, ki bi bil sedel na njegovem prestolu, do prvenca jetnikovega, ki je bil v ječi, tudi vso prvenščino živali.',
        30: 'In vstane Faraon po noči, on in vsi služabniki njegovi in vsi Egipčani, in nastalo je veliko vpitje po Egiptu, kajti ni bilo hiše, v kateri bi ne bilo mrtveca.',
        31: 'In pokliče Mojzesa in Arona po noči in veli: Vstanite in odidite izmed ljudstva mojega, vidva in sinovi Izraelovi, in pojdite, služite Gospodu, kakor sta govorila.',
        32: 'Tudi črede svoje in goveda svoja vzemite s seboj, kakor sta govorila, in pojdite; in me tudi blagoslovite!',
        33: 'In Egipčani so ljudstvo silili, da se hitro odpravi iz dežele; kajti govorili so: Vsi poginemo!',
        34: 'In vzelo je ljudstvo testo svoje, preden se je skisalo, in svoje ponvice za pečenje, zavite v plaščih, na rame svoje.',
        35: 'In storili so sinovi Izraelovi, kakor je bil govoril Mojzes, in izprosili so od Egipčanov srebrnih in zlatih dragotin in oblačil.',
        36: 'Gospod pa je podelil ljudstvu milost v očeh Egipčanov, da so jim dali, česar so prosili. In oplenili so Egipčane.',
        37: 'In odrinili so sinovi Izraelovi iz Ramesesa v Sukot, okoli šeststo tisoč pešcev, mož brez otrok.',
        38: 'Pa tudi dosti mešane druhali je šlo gori ž njimi, in črede in goveda, živine jako veliko.',
        39: 'In spekli so iz testa, ki so ga prinesli iz Egipta, opresne podpepelnike; kajti ni bilo skvašeno, ker so jih spodili iz Egipta, da se niso smeli obotavljati, pa tudi brašna si niso utegnili pripraviti.',
        40: 'In prebivanja Izraelovih sinov, odkar so bivali v Egiptu, je bilo štiristo in trideset let.',
        41: 'In zgodilo se je ob koncu teh štiristo in tridesetih let, zgodilo se je ravno tisti dan, da so odrinile vse vojske Gospodove iz Egipta.',
        42: 'To je noč, ki naj se slovesno praznuje Gospodu, ker jih je odpeljal iz dežele Egiptovske; to je noč Gospodova, ki naj se slovesno praznuje pri vseh Izraelovih sinovih v njih pokolenjih.',
        43: 'In govoril je Gospod Mojzesu in Aronu: To bodi postava o velikonočnem jagnjetu: Noben tujec ne sme jesti od njega.',
        44: 'Vsakega hlapca pa, ki ga je kdo kupil z denarjem, obreži, potem naj jé od njega.',
        45: 'Priseljenec in najemnik ne jej od njega.',
        46: 'V eni hiši se bo jedlo: nič mesa njegovega ne nosite iz hiše in kosti nobene mu ne zlomite.',
        47: 'Vsa občina Izraelova naj ga obhaja.',
        48: 'Če pa pri tebi biva tujec in želi obhajati pasho Gospodu, naj se obreže vsak moški, in potem naj pristopi in jo praznuje, in bodi on kakor rojen v deželi. Ali noben neobrezanec ne jej od njega.',
        49: 'Ista postava veljaj za domačina in za tujca, ki biva med vami.',
        50: 'In vsi sinovi Izraelovi so to storili: kakor je bil ukazal Gospod Mojzesu in Aronu, tako so storili.',
        51: 'In zgodilo se je ravno tisti dan, da je Gospod peljal sinove Izraelove iz Egiptovske dežele po njih vojnih krdelih.',
    },
    13: {
        1: 'In govoril je Gospod Mojzesu, rekoč:',
        2: 'Posveti meni vse prvorojeno, vse, kar predre maternico med sinovi Izraelovimi, od človeka do živali: moje bodi.',
        3: 'In Mojzes je govoril ljudstvu: Spominjajte se tega dne, katerega ste šli iz Egipta, iz hiše sužnosti, zakaj z mogočno roko vas je izpeljal Gospod odtod; in nič kvašenega ne smete jesti.',
        4: 'Današnjega dne, v mesecu Abibu, odhajate.',
        5: 'In ko te privede Gospod v deželo Kanaancev in Hetejcev in Amorejcev in Hevejcev in Jebusejcev, za katero je bil prisegel očetom tvojim, da ti jo dá, deželo, ki v njej teče mleko in med: tedaj opravljaj to službo v temle mesecu.',
        6: 'Sedem dni boš jedel opresnike, in sedmi dan bo praznik Gospodu.',
        7: 'Opresniki se bodo jedli sedem dni, in ne sme biti pri tebi nič okvašenega in ne sme biti pri tebi nič kvasu v vseh krajih tvojih.',
        8: 'In oznaniš ta dan sinu svojemu, rekoč: Delam to zaradi tega, kar je meni storil Gospod, ko sem šel iz Egipta.',
        9: 'In to ti bodi v znamenje na roki tvoji in kakor spominski list med tvojimi očmi, zato da bode zakon Gospodov v ustih tvojih: zakaj z mogočno roko te je peljal Gospod iz Egipta.',
        10: 'Zatorej izpolnjuj to postavo v času za to določenem, leto za letom.',
        11: 'In ko te privede Gospod v deželo Kanaancev, kakor je prisegel tebi in očetom tvojim, in ko ti jo dá,',
        12: 'tedaj odmeni vse, kar predre maternico, Gospodu; tudi vsakega prvenca živine, ki jo boš imel, moškega spola, daj Gospodu.',
        13: 'A vsakega prvenca od osla odkupi z jagnjetom, če ga pa ne odkupiš, zlomi mu šijnjak; tudi odkupi vse prvorojence ljudi med sinovi svojimi.',
        14: 'In če te v prihodnjih časih vpraša sin tvoj, rekoč: Kaj pomeni to? mu odgovori: Z roko mogočno nas je peljal Gospod iz Egipta, iz hiše sužnosti.',
        15: 'In ker je bil Faraon trdovraten in nas ni hotel izpustiti, je Gospod udaril vse prvorojence v Egiptovski deželi, od prvenca človeka do prvorojene živali: zato darujem Gospodu vse prvence samce, vse prvorojence izmed otrok svojih pa odkupujem.',
        16: 'In to ti bodi za znamenje na roki tvoji in kakor bi viselo za spomin med tvojimi očmi; zakaj s premogočno roko nas je peljal Gospod iz Egipta.',
        17: 'In zgodilo se je, ko je Faraon odpustil ljudstvo, da jih Bog ni peljal po poti skozi Filistejsko deželo, čeprav je bila blizu; rekel je namreč Bog: Morda bi bilo ljudstvu žal, ko bi videli vojno; in bi se povrnili v Egipt.',
        18: 'Ampak Bog jih je obrnil na pot preko puščave k Rdečemu morju; in sinovi Izraelovi so šli oboroženi iz dežele Egiptovske.',
        19: 'In Mojzes je vzel kosti Jožefove s seboj, kajti on je s prisego zavezal sinove Izraelove, rekoč: Gotovo vas obišče Bog; odnesite potem kosti moje odtod s seboj!',
        20: 'In odrinili so iz Sukota, in taborili so v Etamu, kraj puščave.',
        21: 'In Gospod je šel pred njimi, po dnevi v oblakovem stebru, da bi jih vodil po poti, po noči pa v ognjenem stebru, da bi jim svetil: tako so mogli potovati po dne in po noči.',
        22: 'Nikoli se ni umaknil oblakov steber po dnevi, ne ognjeni steber po noči izpred ljudstva.',
    },
    14: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Govóri sinovom Izraelovim, naj se vrnejo in tabore pred Pihahirotom, med Migdolom in morjem, pred Baalzefonom; njemu nasproti razpnite šatore pri morju.',
        3: 'Kajti Faraon poreče o Izraelovih sinovih: Zašli so v deželi, puščava jih je obdala.',
        4: 'Jaz pa hočem otrditi srce Faraonovo, da bo hitel za njimi, in hočem se oslaviti na Faraonu in na vsej vojski njegovi; in Egipčani spoznajo, da sem jaz Gospod. In storili so tako.',
        5: 'In ko so kralju egiptovskemu sporočili, da je ljudstvo zbežalo, se izpremeni srce Faraonovo in služabnikov njegovih proti ljudstvu, in reko: Kaj smo to storili, da smo odpustili Izraelce iz službe svoje!',
        6: 'Zapreže torej svoj voz ter vzame ljudstvo svoje s seboj;',
        7: 'vzame namreč šeststo izbranih voz in vse vozove egiptovske in bojevnike na vsakem iz njih.',
        8: 'In Gospod je otrdil srce Faraona, kralja egiptovskega, da je dirjal za sinovi Izraelovimi. A sinovi Izraelovi so odhajali po visoki roki.',
        9: 'Egipčani pa so hiteli za njimi, in vsi konji in vozovi Faraonovi, konjiki njegovi in vojska njegova so jih došli, ko so taborili pri morju ob Pihahirotu, nasproti Baalzefonu.',
        10: 'Ko se je pa bližal Faraon, povzdignejo sinovi Izrelovi oči, in glej, Egipčani gredo za njimi; in ustrašijo se sinovi Izrelovi zelo in vpijejo h Gospodu.',
        11: 'In govore Mojzesu: Ni li morda bilo nobenih grobov v Egiptu, da si nas odpeljal, da umrjemo v puščavi? Zakaj si nam to storil, da si nas izvedel iz Egipta?',
        12: 'Ali to ni beseda, ki smo ti jo govorili v Egiptu, rekoč: Pusti nas, naj služimo Egipčanom, zakaj bolje nam je služiti Egipčanom nego umreti v puščavi.',
        13: 'In Mojzes veli ljudstvu: Ne bojte se, stojte trdno in glejte rešitev Gospodovo, ki jo za vas izvrši danes; zakaj Egipčanov, ki jih danes vidite, ne boste nikdar več videli na veke.',
        14: 'Gospod se bo za vas bojeval, vi pa bodite mirni!',
        15: 'In Gospod reče Mojzesu: Zakaj vpiješ k meni? Véli Izraelovim sinovom, naj gredo naprej!',
        16: 'Ti pa povzdigni palico svojo in iztegni roko nad morje ter ga razdeli, in šli bodo sinovi Izraelovi sredi morja po suhem.',
        17: 'In glej, jaz otrdim srce Egipčanov, da pojdejo za vami; in hočem se oslaviti na Faraonu in na vsej vojski njegovi in na vseh vozovih in konjikih njegovih.',
        18: 'In Egipčani spoznajo, da sem jaz Gospod, kadar se oslavim na Faraonu, na njegovih vozeh in konjikih njegovih.',
        19: 'In vzdignil se je angel Gospodov, ki je šel pred vojsko Izraelcev, in gre zadaj za njimi, in oblakov steber izgine izpred njih in se postavi za njimi,',
        20: 'in pride med vojsko Egipčanov in vojsko Izraelovo; in tam je oblak delal temo, tu pa je razsvetljeval noč. In eni se niso drugim približali celo noč.',
        21: 'Mojzes torej iztegne roko nad morje, in Gospod je odpravil morje s silnim vzhodnikom, ki je pihal celo noč, in je napravil v morju suha tla, in voda se je razdelila.',
        22: 'In sinovi Izraelovi so šli sredi morja po suhem, in vode so jim bile kakor zidovje na desni in na levi.',
        23: 'In Egipčani so gnali za njimi, in prišli so vsi konji Faraonovi, vozovi in konjiki njegovi v sredo morja.',
        24: 'In zgodi se ob jutranji straži, da pogleda Gospod na vojsko Egipčanov iz ognjenega in oblakovega stebra in napravi zmešnjavo v vojski Egipčanov;',
        25: 'in stori, da se kolesa vozom izmaknejo, tako da so s težavo vozili. In Egipčani reko: Bežímo pred Izraelom, kajti Gospod se bojuje zanje proti Egiptu.',
        26: 'In Gospod reče Mojzesu: Iztegni roko nad morje, da se vode povrnejo na Egipčane, na njih vozove in jezdece.',
        27: 'Tedaj iztegne Mojzes roko po morju, in povrnilo se je morje ob jutranjem svitu v navadno valovanje svoje; in Egipčani so bežali proti njemu, in Gospod jih je pognal v sredo vodovja.',
        28: 'In povrnile so se vode in zagrnile vozove in konjištvo vse vojske Faraonove, ki je šla za Izraelci v morje; ni preostalo izmed njih še enega ne.',
        29: 'Ali sinovi Izraelovi so šli sredi morja po suhem, in vode so jim bile v zidovje na desni in na levi.',
        30: 'Tako je otel Gospod tisti dan Izraela iz roke Egipčanov. In videl je Izrael Egipčane mrtve ob bregu morja.',
        31: 'In videl je Izrael preveliko moč, ki jo je bil Gospod pokazal nad Egipčani, in balo se je ljudstvo Gospoda in verovalo je Gospodu in Mojzesu, njegovemu služabniku.',
    },
    15: {
        1: 'Tedaj je pel Mojzes in sinovi Izraelovi tole pesem Gospodu, govoreč takole: Pel bom Gospodu, ker se je slavno poveličal: konja in jezdeca njegovega je pahnil v morje.',
        2: 'Moč moja in pesem moja je Gospod, on mi je postal rešitev. Ta je moj Bog mogočni, slavil ga bom, očeta mojega Bog, poveličeval ga bom.',
        3: 'Gospod je pravi vojščak, Gospod je ime njegovo.',
        4: 'Faraonove vozove in vojsko njegovo je pahnil v morje, in najizvrstnejši vojvode njegovi so se pogreznili v Rdeče morje.',
        5: 'Valovje jih je zagrnilo, pogreznili so se v globočine kakor kamen.',
        6: 'Desnica tvoja, Gospod, se je poveličala v moči, desnica tvoja, Gospod, je strla sovražnika.',
        7: 'In v obilosti svojega veličastva si porazil nje, ki so se vzpenjali zoper tebe; izpustil si jezo svojo, ta jih je požrla kot strnišče.',
        8: 'In z dihom nozdrvi tvojih so se nakopičile vode, tekoče vode so se postavile kakor jez, zgostili so se valovi v srcu morja.',
        9: 'Rekel je sovražnik: Poženem se za njim, dohitim ga, delil bom plen, nasitila se jih bo pohlepnost moja; izderem meč svoj, roka moja jih pokonča.',
        10: 'A ti si pihnil z vetrom svojim – morje jih je zagrnilo, potopili so se kakor svinec v silnih vodah.',
        11: 'Kdo je tebi enak med bogovi, Gospod? kdo je kakor ti, poveličan v svetosti, poln vzvišene slave, čudeže delajoč?',
        12: 'Iztegnil si desnico svojo, in požrla jih je zemlja.',
        13: 'Ti si peljal v usmiljenju svojem ljudstvo, ki si ga bil odkupil; peljal si jih v moči svoji k prebivališču svetosti svoje.',
        14: 'Začuvši to, so vztrepetali narodi, strah je prevzel prebivalce filistejske.',
        15: 'Tedaj so se prestrašili vojvode edomski, trepet se je polastil korenjakov moabskih, zbali so se prebivalci kanaanski.',
        16: 'Naj jih obidejo strahovi in prešine groza, zaradi mogočnosti tvoje roke naj otrpnejo kakor kamen, dokler ne prejde mimo ljudstvo tvoje, Gospod, dokler ne prejde mimo ljudstvo, ki si ga sebi pridobil.',
        17: 'Vpeljal jih boš in jih zasadil na gori dediščine svoje, na mesto, ki si ga pripravil, Gospod, za prebivanje svoje, v svetišče, Gospod, ki so ga utrdile roke tvoje.',
        18: 'Gospod bo kraljeval vselej in vekomaj!',
        19: 'Kajti konji Faraonovi ž njegovimi vozovi in konjiki so šli v morje, in Gospod je poslal nadnje vode morja, sinovi Izraelovi pa so šli po suhem sredi morja.',
        20: 'In Mirjama prorokinja, sestra Aronova, je vzela boben v roko, in vse žene so šle za njo z bobni in v kolu.',
        21: 'In Mirjama jim je odpevala: Pojte Gospodu, ker se je slavno poveličal: konja in jezdeca njegovega je pahnil v morje.',
        22: 'In Mojzes ukaže, da odrine Izrael od Rdečega morja, in šli so v puščavo Sursko. In potujoč tri dni po puščavi, niso našli vode.',
        23: 'In prišli so v Maro, pa niso mogli piti vode iz Mare, ker je bila grenka. Zato se imenuje ta kraj Mara.',
        24: 'In ljudstvo je mrmralo zoper Mojzesa, govoreč: Kaj bomo pili?',
        25: 'On pa je klical h Gospodu, in pokaže mu Gospod les, in ko ga je vrgel v vodo, je voda postala sladka. Tu mu je dal postavo in pravice, in tu ga je izkusil',
        26: 'in rekel: Ako boš res poslušal glas Gospoda, svojega Boga, in delal, kar je prav v očeh njegovih, in pazil na zapovedi njegove in čuval vse postave njegove, ne pošljem nad te nobene teh bolezni, ki sem jih poslal nad Egipt, zakaj jaz sem Gospod, zdravnik tvoj.',
        27: 'In prišli so v Elim, kjer je bilo dvanajst studencev in sedemdeset palm, in utaborili so se tam pri vodah.',
    },
    16: {
        1: 'In odrinili so iz Elima, in prišla je vsa občina sinov Izraelovih v puščavo Sinsko, ki je med Elimom in med Sinajem, petnajsti dan drugega meseca po svojem odhodu iz Egipta.',
        2: 'In mrmrala je vsa občina sinov Izraelovih zoper Mojzesa in Arona v puščavi,',
        3: 'in rekli so jima sinovi Izraelovi: O, da bi bili umrli po roki Gospodovi v deželi Egiptovski, ko smo sedeli pri loncih mesa in jedli kruh dosita! kajti izpeljala sta nas v to puščavo, da vso tole množico pomorita z lakoto!',
        4: 'Tedaj reče Gospod Mojzesu: Glej, dežil vam bom kruh z neba; ljudstvo pa naj hodi in pobira vsak dan, kolikor tisti dan potrebuje, da ga izkusim, ali bo po mojem zakonu živelo ali ne.',
        5: 'In šesti dan naj pripravijo, kar so nabrali, in bode dvakrat toliko, po kolikor so nabrali vsak dan.',
        6: 'In Mojzes in Aron sporočita vsem sinovom Izraelovim: Zvečer spoznate, da vas je Gospod peljal iz dežele Egiptovske,',
        7: 'in zjutraj boste videli slavo Gospodovo, ker je on slišal mrmranje vaše zoper Gospoda, kajti kaj sva midva, da mrmrate zoper naju?',
        8: 'In reče Mojzes: Po tem to spoznate, ko vam Gospod dá zvečer jesti mesa in zjutraj kruha dosita; ker je Gospod slišal mrmranje vaše, s katerim ste godrnjali zoper njega. Kaj sva pač midva? Ne zoper naju je mrmranje vaše, ampak zoper Gospoda.',
        9: 'In veli Mojzes Aronu: Govori vsej občini sinov Izraelovih: Približajte se Gospodu, kajti slišal je mrmranje vaše.',
        10: 'In zgodilo se je, ko je Aron govoril vsej občini sinov Izraelovih, da se obrnejo proti puščavi, in glej, slava Gospodova se je prikazala v oblaku.',
        11: 'In Gospod je govoril Mojzesu, rekoč:',
        12: 'Slišal sem mrmranje Izraelovih otrok; povej jim tole: Proti večeru boste jedli meso in zjutraj se nasitili kruha, in spoznali boste, da sem jaz Gospod, vaš Bog.',
        13: 'In zgodi se zvečer, da so priletele prepelice in pokrile tabor; in zjutraj je ležala rosa okrog tabora.',
        14: 'Ko se je pa rosa vzdignila, glej, po površju puščave je nekaj drobnega, luskinastega, drobnega kakor slana na tleh.',
        15: 'In sinovi Izraelovi, videč to, so rekli drug drugemu: Kaj je to? niso namreč vedeli, kaj je. In Mojzes jim reče: To je tisti kruh, ki vam ga je dal Gospod za jed.',
        16: 'To je beseda, ki jo je zapovedal Gospod: Vsak naj nabere tega, kolikor more pojesti; gomer za vsako glavo, po številu vaših duš; vsak naj vzame tega za tiste, ki so v njegovem šatoru.',
        17: 'In storili so tako sinovi Izraelovi, in nabrali so, eden več, drugi manj.',
        18: 'In so merili z gomerom: in kdor je mnogo nabral, mu ni ničesar preostalo, in kdor je malo nabral, mu ni ničesar manjkalo; vsakdo je nabral, prav kolikor je mogel snesti.',
        19: 'In Mojzes jim veli: Nihče naj ne pusti kaj tega do jutra!',
        20: 'Toda niso Mojzesa poslušali, in nekateri so pustili ostanek do jutra; in zaredili so se v tem črvi, in usmradilo se je. In razsrdil se je Mojzes nad njimi.',
        21: 'In nabirali so jutro za jutrom, vsakdo, kolikor je mogel pojesti; kadar pa je solnce pripekalo, se je raztajalo.',
        22: 'In zgodi se šesti dan, da nabero kruha dvakrat toliko, dva gomera za enega. In pridejo vsi prvaki občine povedat to Mojzesu.',
        23: 'In on jim reče: To je, kar je govoril Gospod: Jutri bo praznik, svet počitek Gospodu; kar hočete peči, pecite, in kar hočete kuhati, kuhajte, in karkoli preostane, denite na stran, da se prihrani do jutra.',
        24: 'Deli so torej to na stran do jutra, kakor je ukazal Mojzes, a ni se usmradilo, tudi ni bilo črvov v tem.',
        25: 'In Mojzes reče: Jejte to danes, kajti danes je praznik Gospodu, danes ne najdete nič tega na polju.',
        26: 'Šest dni boste nabirali, a sedmi dan je počitek, tedaj ne bo tega.',
        27: 'Zgodi se pa sedmi dan, da so šli nekateri izmed ljudstva nabirat, a niso ničesar našli.',
        28: 'In Gospod reče Mojzesu: Doklej se pa boste upirali, da spoštujete ukaze moje in povelja moja?',
        29: 'Glejte, ker vam je Gospod dal praznik, zato vam daje šesti dan kruha za dva dni. Vsakdo naj ostane na svojem, nihče ne odhajaj s svojega kraja sedmi dan!',
        30: 'Počivalo je torej ljudstvo sedmi dan.',
        31: 'In imenovala je hiša Izraelova ta kruh mano; bil je pa kakor belo koriandrovo seme in njegov okus kakor medeni kolači.',
        32: 'In Mojzes je rekel: To je, kar je ukazal Gospod: Poln gomer tega naj se shrani za prihodnje rodove vaše, zato da vidijo kruh, s katerim sem vas hranil v puščavi, ko sem vas peljal iz dežele Egiptovske.',
        33: 'Veli torej Mojzes Aronu: Vzemi posodo in deni vanjo poln gomer mane, in položi jo pred Gospodom, da se hrani za prihodnje rodove vaše.',
        34: 'Kakor je bil ukazal Gospod Mojzesu, tako jo je Aron položil pred pričevanjem, da bodi shranjena.',
        35: 'In jedli so sinovi Izraelovi mano štirideset let, dokler niso prišli v naseljeno deželo; jedli so mano, dokler niso prišli do meje dežele Kanaanske.',
        36: 'Gomer pa je deseti del efe.',
    },
    17: {
        1: 'In vsa občina sinov Izraelovih je šla iz puščave Sinske po postajah svojih na povelje Gospodovo in se je utaborila v Rafidimu; ali ni bilo vode, da bi ljudstvo pilo.',
        2: 'In prepiralo se je ljudstvo z Mojzesom in govorilo: Dajta nam vode, da pijemo! Mojzes jim pa odgovori: Kaj se pričkate z menoj? Zakaj izkušate Gospoda?',
        3: 'In bilo je tam ljudstvo žejno vode in je mrmralo zoper Mojzesa, govoreč: Zakaj si nas izpeljal iz Egipta? da z žejo umoriš mene, otroke moje in živino mojo?',
        4: 'In vpil je Mojzes h Gospodu, rekoč: Kaj naj storim s tem ljudstvom? Še malo, pa me bodo s kamenjem posuli.',
        5: 'In Gospod reče Mojzesu: Stopi na čelo ljudstva in vzemi s seboj nekoliko starejšin Izraelovih; in palico svojo, s katero si udaril reko, vzemi v roko in pojdi.',
        6: 'Glej, jaz bom stal pred teboj na Horebu tam na skali; ti pa udari skalo, in voda priteče iz nje, da bo ljudstvo pilo. In storil je Mojzes tako pred očmi starejšin Izraelovih.',
        7: 'In ime tega mesta je imenoval Masa in Meriba zaradi prepira sinov Izraelovih in ker so izkušali Gospoda, govoreč: Ali je Gospod sredi nas ali ga ni?',
        8: 'In prišel je Amalek in se je bojeval z Izraelom v Rafidimu.',
        9: 'In Mojzes veli Jozuetu: Izberi nam može in pojdi, bojuj se z Amalekom; jaz bom jutri stal na vrhu hriba s palico Božjo v roki svoji.',
        10: 'In storil je Jozue, kakor mu je rekel Mojzes, da bi se bojeval z Amalekom. Mojzes pa in Aron in Hur so stopili na vrh hriba.',
        11: 'In dokler je Mojzes kvišku držal roko, je zmagoval Izrael, kadar pa je povesil roko, je premagal Amalek.',
        12: 'A roke Mojzesove so se utrudile. Vzameta torej kamen in mu ga podložita, in on sede nanj; Aron pa in Hur podpirata roke njegove, eden na tej, drugi pa na drugi strani. Tako so njegove roke ostale trdne do solnčnega zahoda.',
        13: 'In porazil je Jozue Amaleka in ljudstvo njegovo z meča ostrino.',
        14: 'Tedaj je Gospod rekel Mojzesu: Zapiši to v knjigo za spomin in ponavljaj vpričo Jozueta, da bom dočista izbrisal spomin Amalekov izpod neba.',
        15: 'In Mojzes postavi oltar in imenuje ime njegovo: Jehova nisi,',
        16: 'in reče: Res, roka je vzdignjena proti prestolu Gospodovemu: vojska Gospodova bo zoper Amaleka od roda do roda.',
    },
    18: {
        1: 'In slišal je Jetro, duhovnik madianski, tast Mojzesov, o vsem, kar je storil Bog Mojzesu in Izraelu, ljudstvu svojemu, da je Gospod odpeljal Izraela iz Egipta.',
        2: 'In vzame Jetro, tast Mojzesov, Ziforo, Mojzesovo ženo (potem ko jo je bil nazaj poslal),',
        3: 'in njena dva sinova, katerih imeni sta: prvega Gerson, ker je rekel Mojzes: „Priseljenec sem v tuji zemlji“,',
        4: 'in drugega Eliezer, „kajti Bog očeta mojega mi je bil v pomoč in me je otel meča Faraonovega“;',
        5: 'in pride Jetro, tast Mojzesov, ž njegovima sinoma in njegovo ženo k Mojzesu v puščavo, kjer je taboril pri gori Božji.',
        6: 'In sporoči Mojzesu: Jaz, tast tvoj Jetro, sem prišel k tebi in tvoja žena in ž njo dva sinova njena.',
        7: 'In Mojzes pride naproti tastu svojemu, in prikloni se ter ga poljubi; nato vprašata drug drugega, če se jima dobro godi, in gresta v šator.',
        8: 'In Mojzes pripoveduje tastu svojemu vse, kar je storil Gospod nad Faraonom in nad Egipčani zaradi Izraela, in o vseh težavah, ki so jih prebili na potovanju, in kako jih je reševal Gospod.',
        9: 'In vzradostil se je Jetro ob vsej dobroti, ki jo je Gospod storil Izraelu, da ga je otel iz roke Egipčanov.',
        10: 'In reče Jetro: Hvaljen bodi Gospod, ki vas je otel iz roke Egipčanov in iz roke Faraonove, ki je otel to ljudstvo izpod pesti Egipčanov.',
        11: 'Zdaj vem, da je Gospod večji od vseh bogov: zakaj ravno v tem, s čimer so prevzetovali, se je povišal nad nje.',
        12: 'In daroval je Jetro, tast Mojzesov, žgalne in klalne daritve Bogu; Aron pa in vsi starejšine Izraelovi so prišli, da bi jedli kruh s tastom Mojzesovim pred obličjem Božjim.',
        13: 'In zgodi se zjutraj, da se je usedel Mojzes, da bi sodil ljudstvu; in ljudstvo je stalo pred Mojzesom od jutra do večera.',
        14: 'In videl je tast Mojzesov vse, kar dela z ljudstvom, in je rekel: Kakšno opravilo je to, ki ga imaš z ljudstvom? Zakaj sediš ti edini, vse ljudstvo pa stoji pred teboj od jutra do večera?',
        15: 'In odgovori Mojzes tastu svojemu: Ljudstvo prihaja k meni posvetovat se z Bogom.',
        16: 'Ko imajo kako pravdo, pridejo k meni, in jaz razsojam med njimi in jim naznanjam Božja pravila in postave njegove.',
        17: 'In njegov tast mu reče: Ni dobro, kar delaš.',
        18: 'Preveč se utrudiš in tudi to ljudstvo, ki je pri tebi; pretežavno je to delo zate; sam ga ne moreš vršiti.',
        19: 'Zdaj pa čuj moj glas, hočem ti dati svet, in Bog bode s teboj: Bodi zastopnik ljudstva pred Bogom in donašaj njih zadeve pred Boga;',
        20: 'in razjasnjuj jim pravila in postave in oznanjaj jim pot, po katerem naj hodijo, in delo, ki naj ga opravljajo.',
        21: 'Toda ozri se med vsem ljudstvom po vrlih možeh, bogaboječih, ki so vdani resnici, sovražni krivičnemu dobičku; in postavi jih za načelnike čez tisoč, načelnike čez sto, načelnike čez petdeset in za načelnike čez deset.',
        22: 'Oni naj sodijo ljudstvu vsak čas; in vse velike zadeve naj razgrnejo tebi, karkoli pa bo manjšega, naj sodijo sami: tako olajšaj sebi, in oni naj nosijo breme s teboj.',
        23: 'Če ta nasvet izpolniš in ti Bog to ukaže, boš mogel prestati, pa tudi to ljudstvo pride vse do kraja svojega v miru.',
        24: 'In Mojzes je slušal glas svojega tasta ter storil vse, kar mu je rekel.',
        25: 'In izbral je Mojzes vrlih mož izmed vseh Izraelcev in jih postavil za poglavarje nad ljudstvom: za načelnike čez tisoč, načelnike čez sto, načelnike čez petdeset in za načelnike čez deset.',
        26: 'In sodili so ljudstvu vsakteri čas: težke stvari so razgrinjali Mojzesu, karkoli pa je bilo manjšega, so sodili sami.',
        27: 'In Mojzes se je poslovil od svojega tasta, ta pa je šel v deželo svojo.',
    },
    19: {
        1: 'Tretji mesec po odhodu sinov Izraelovih iz dežele Egiptovske, v isti dan so prišli v Sinajsko puščavo.',
        2: 'Odrinili so bili iz Rafidima in prišli v Sinajsko puščavo, in utaborili so se v puščavi; tamkaj je Izrael gorovju nasproti razpel šatore.',
        3: 'In Mojzes je stopil gori k Bogu, in Gospod mu je klical z gore, govoreč: Tako govóri hiši Jakobovi in oznani sinovom Izraelovim:',
        4: 'Sami ste videli, kaj sem storil Egiptu in kako sem vas nosil na orlovih perotih in vas privedel k sebi.',
        5: 'In sedaj, če boste resno poslušali glas moj in držali zavezo mojo, bodete moja dragotina pred vsemi narodi, kajti moja je vsa zemlja;',
        6: 'in bodete mi kraljestvo duhovnikov in svet narod. To so besede, ki jih boš govoril sinovom Izraelovim.',
        7: 'In Mojzes pride in skliče starejšine ljudstva in jim predloži vse te besede, ki mu jih je ukazal Gospod.',
        8: 'In odgovori vse ljudstvo hkrati, rekoč: Storiti hočemo vse, kar je govoril Gospod. In sporočil je Mojzes besede ljudstva Gospodu.',
        9: 'In Gospod reče Mojzesu: Glej, jaz pridem k tebi v temnem oblaku, zato da bi čulo ljudstvo govor moj s teboj ter da bi ti tudi verovalo vekomaj. In Mojzes je oznanil Gospodu besede ljudstva.',
        10: 'In Gospod reče Mojzesu: Idi k ljudstvu in posveti jih danes in jutri, in naj operejo oblačila svoja,',
        11: 'in naj bodo pripravljeni za tretji dan, zakaj tretjega dne pride Gospod pred očmi vsega ljudstva na goro Sinaj.',
        12: 'In napravi mejo ljudstvu okrog in reci: Varujte se stopiti na goro ali dotekniti se njenega kraja; kdorkoli se gore dotakne, mora umreti.',
        13: 'Ne bo se ga doteknila nobena roka, ampak kamenali ga bodo ali ustrelili, bodi žival, bodi človek, živ ne sme ostati. Ko bo trobenta zategnjeno donela, pojdejo proti gori.',
        14: 'In prišel je Mojzes doli z gore k ljudstvu, in posvetil je ljudstvo, in oprali so oblačila svoja.',
        15: 'In rekel je ljudstvu: Bodite pripravljeni za tretji dan, ne približajte se ženi.',
        16: 'In ko napoči jutro tretjega dne, nastane grmenje in bliskanje in temni oblaki na gori in silno močne trombe glas; in treslo se je vse ljudstvo, ki je bilo v taboru.',
        17: 'In Mojzes je vedel ljudstvo iz tabora Bogu naproti; in postavili so se spodaj ob gori.',
        18: 'Vsa gora Sinaj pa se je kadila, zato ker je bil Gospod stopil nanjo v ognju, in njen dim se je valil kvišku kakor dim iz topilne peči; in vsa gora se je silno tresla.',
        19: 'In glas trombe je bil čimdalje močnejši; Mojzes je govoril, in Bog mu je odgovarjal z glasom.',
        20: 'In Gospod je stopil doli na goro Sinaj, na vrh gore, in poklical je Gospod Mojzesa na vrh gore, in Mojzes je šel tja gori.',
        21: 'In Gospod reče Mojzesu: Stopi doli, posvari ljudstvo, naj nikar naprej ne silijo h Gospodu, hoteč gledati, da jih ne pade veliko.',
        22: 'Pa tudi duhovniki, ki pristopajo h Gospodu, naj se posveté, da se Gospod ne zažene vanje.',
        23: 'In Mojzes reče Gospodu: Ljudstvo ne more stopiti na goro Sinaj, ker si nas sam posvaril, rekoč: Napravi ograjo okoli gore in posveti jo.',
        24: 'In Gospod mu reče: Idi doli, in potem pridi sem ti in Aron s teboj; a duhovniki in ljudstvo naj ne silijo naprej, hoteč pristopiti h Gospodu, da se ne zažene vanje.',
        25: 'In Mojzes je prišel doli k ljudstvu in jim povedal.',
    },
    20: {
        1: 'In Bog je govoril vse te besede, rekoč:',
        2: 'Jaz sem Gospod, Bog tvoj, ki sem te izpeljal iz dežele Egiptovske, iz hiše sužnosti.',
        3: 'Ne imej drugih bogov zraven mene.',
        4: 'Ne delaj si rezanih podob niti nikakršnih podob tega, kar je zgoraj na nebu, kar je spodaj na zemlji in kar je v vodah pod zemljo:',
        5: 'ne moli jih in ne časti jih, zakaj jaz sem Gospod, Bog tvoj, Bog mogočni, goreči, ki obiskujem krivico očetov na sinovih do tretjega in četrtega pokolenja tistih, ki me sovražijo,',
        6: 'in izkazujem milost tisočim onih, ki me ljubijo in izpolnjujejo zapovedi moje.',
        7: 'Ne imenuj po nemarnem imena Gospoda, svojega Boga, zakaj Gospod ne pusti brez kazni njega, ki bi imenoval ime njegovo po nemarnem.',
        8: 'Spominjaj se sobotnega dne, da ga posvečuješ.',
        9: 'Šest dni boš delal in opravljal ves posel svoj,',
        10: 'ali sedmi dan je čas počitka Gospodu, Bogu tvojemu: v njem ne opravljaj nobenega dela, ne ti, ne sin tvoj, ne hči tvoja, ne hlapec tvoj, ne dekla tvoja, ne živina tvoja, niti tujec, ki je v vratih tvojih.',
        11: 'Zakaj v šestih dneh je ustvaril Gospod nebo in zemljo, morje in vse, kar je v njih, in sedmi dan je počival: zato je blagoslovil sobotni dan in ga posvetil.',
        12: 'Spoštuj očeta svojega in mater svojo, da se podaljšajo dnevi tvoji v deželi, katero ti da Gospod, Bog tvoj.',
        13: 'Ne ubijaj.',
        14: 'Ne prešeštvuj.',
        15: 'Ne kradi.',
        16: 'Ne govori krivega pričevanja zoper bližnjega svojega.',
        17: 'Ne poželi hiše bližnjega svojega, ne poželi žene bližnjega svojega, ne hlapca njegovega, ne dekle njegove, ne vola, ne osla njegovega, ne ničesar, kar je bližnjega tvojega.',
        18: 'In vse ljudstvo je čulo grmenje in trombe glas in videlo plamene in kadečo se goro; in ko je ljudstvo to videlo, je trepetalo in se postavilo oddaleč.',
        19: 'In rekli so Mojzesu: Govóri ti z nami, in poslušali bomo; nikar pa naj ne govori z nami Bog, da ne umrjemo.',
        20: 'In Mojzes reče ljudstvu: Ne bojte se, kajti zato, da bi vas izkusil je prišel Bog, in zato, da bode strah njegov pred vašim obličjem da ne grešite.',
        21: 'In stalo je ljudstvo oddaleč, Mojzes pa se je približal temi, v kateri je bil Bog.',
        22: 'In govoril je Gospod Mojzesu: Tako porečeš sinovom Izraelovim: Sami ste videli, da sem iz nebes govoril z vami.',
        23: 'Ne delajte si ničesar zraven mene, bogov iz srebra in bogov iz zlata si nikar ne delajte!',
        24: 'Napraviš mi oltar iz prsti, in na njem boš daroval svoje žgalne in mirovne daritve, svojo drobnico in goved svojo; na vsako mesto, kjerkoli storim, da se bo spominjalo imena mojega, bom prihajal k tebi in te blagoslovil.',
        25: 'In če mi napraviš oltar iz kamenja, ne gradi ga iz rezanih kamenov: kajti ako si vihtel nad njim železo svoje, si ga oskrunil.',
        26: 'Tudi ne boš stopal po stopnicah k oltarju mojemu, da se ne odkrije sramota tvoja pred njim.',
    },
    21: {
        1: 'In to so sodne pravice, ki jim jih predložiš:',
        2: 'Če kupiš hlapca Hebrejca, bo šest let služil, in sedmo leto odide v svobodo brezplačno.',
        3: 'Ako je prišel sam, sam tudi odide; ako je imel ženo, odide žena njegova ž njim.',
        4: 'Ako mu je dal njegov gospodar ženo in mu je rodila sinove ali hčere, tedaj bodo žena in otroci njeni njenega gospodarja, in on odide sam.',
        5: 'Ako bi pa rekel tisti hlapec: Ljubim gospodarja svojega, ženo svojo in otroke svoje, ne maram oditi v svobodo,',
        6: 'tedaj ga pripelje njegov gospodar pred sodnike, in postavi ga k vratom ali k podboju in mu prebodi uho s šilom; in bode mu hlapec za vselej.',
        7: 'Če kdo proda svojo hčer za deklo, ne odide, kakor odhajajo hlapci.',
        8: 'Ako ne bi ugajala svojemu gospodu, ki si jo je zaročil, naj ji dovoli, da se odkupi; tujemu narodu je ne bo smel prodati, ker je nevzesto ravnal ž njo.',
        9: 'Ako jo pa zaroči sinu svojemu, ji izkaži pravico, kakršno imajo hčere.',
        10: 'Ako si vzame drugo za ženo: njenega živeža, njene obleke in zakonske dolžnosti naj ji ne krati.',
        11: 'In ako ji ne da teh treh reči, naj odide brezplačno, brez odkupnine.',
        12: 'Kdor udari človeka, da umrje, mora umreti.',
        13: 'Ako ga pa ni zalezoval, a Bog je pripustil, da je roka njegova smrtno zadela, ti odločim mesto, kamor naj zbeži.',
        14: 'Ako pa kdo snuje zlobo proti bližnjemu svojemu, da bi ga s prevaro usmrtil, ga odpraviš celo od oltarja mojega, da umrje.',
        15: 'In kdor udari očeta svojega ali mater svojo, mora umreti.',
        16: 'In kdor ukrade človeka in ga proda, ali če ga najdejo v roki njegovi, mora umreti.',
        17: 'In kdor preklinja očeta svojega ali mater svojo, mora umreti.',
        18: 'Če se moža spreta in drug drugega udarita s kamenom ali pa s pestjo, pa ne umre, ampak obleži v postelji:',
        19: 'ko zopet vstane in hodi zunaj ob palici, ne bodi kaznjen tisti, ki ga je udaril; samo naj mu poplača, kar je zamudil, in poskrbi mu, da popolnoma ozdravi.',
        20: 'In če kdo tepe hlapca svojega ali deklo svojo s šibo, da umrjeta pod roko njegovo, mora biti kaznovan;',
        21: 'ako pa preživita eden ali dva dni, ne bodi kaznovan, ker sta njegov denar.',
        22: 'In če se možje tepó in udari kdo nosečo ženo, da izgubi zarod, druga poškodba pa se ji ne zgodi: mora plačati kazen v denarju, kolikor mu naloži mož tiste žene, in plača naj, kakor bodo sodniki določili.',
        23: 'Če se pa zgodi poškodba, se mora dati življenje za življenje,',
        24: 'oko za oko, zob za zob, roka za roko, noga za nogo,',
        25: 'opeklina za opeklino, rana za rano, bula za bulo.',
        26: 'In če kdo udari svojega hlapca ali svojo deklo v oko in ga skazi, naj ga odpusti v svobodo za oko njegovo.',
        27: 'In če izbije zob svojemu hlapcu ali dekli svoji, naj ga odpusti v svobodo za zob njegov.',
        28: 'In če vol pobode moža ali ženo, da umrjeta, bodi vol kamenan in mesa njegovega ne smejo jesti; volov gospodar pa bodi brez krivde.',
        29: 'Ako pa je bil vol bodljiv poprej in so posvarili gospodarja njegovega, pa ga ni zapiral, in usmrti moža ali ženo, naj kamenajo vola in tudi gospodarja njegovega naj umoré.',
        30: 'Če se mu pa naloži poravnava, naj plača za odrešitev življenja svojega vse, kolikor mu nalože.',
        31: 'Najsi je pobodel sina ali hčer, naj ravnajo ž njim po tem sodnem pravu.',
        32: 'Ako pa vol pobode hlapca ali deklo, naj plača njegov lastnik njiju gospodarju trideset srebrnikov, in vola naj s kamenjem posujejo.',
        33: 'In če kdo odpre jamo ali če kdo izkoplje jamo in je ne pokrije, in pade vanjo vol ali osel,',
        34: 'naj povrne posestnik jame: v denarju naj plača njiju gospodarju, mrtva žival pa bodi njegova.',
        35: 'In če vol rani vola sosedovega, da pogine, naj prodasta živega vola in si razdelita izkupiček, pa tudi mrtvega vola.',
        36: 'Ako pa se je vedelo, da je bil vol bodljiv poprej in ga ni zapiral njegov gospodar, naj povrne vola za vola, in mrtvi bodi njegov.',
    },
    22: {
        1: 'Če kdo ukrade vola ali ovco in zakolje ali proda živinče, naj povrne pet volov za vola in štiri ovce za ovco.',
        2: 'Ako se zasači tat pri vlomu in ga kdo udari, da umrje, ne bodi kriv krvi;',
        3: 'ako pa mu je že izšlo solnce, bodi sojen zaradi krvi. Tat mora vsekakor povrniti: ako nima ničesar, bodi prodan za svojo tatvino.',
        4: 'Ako se najde v roki njegovi, kar je ukradel, živo, bodi vol ali osel ali ovca, naj povrne dvojno.',
        5: 'Če kdo popase njivo ali vinograd in izpusti živino svojo, da naj se pase na njivi drugega, povrne škodo z najboljšim, kar ima na njivi svoji in v vinogradu svojem.',
        6: 'Ako nastane ogenj in se vname trnje in zgori kopica snopja ali rastoče žito ali polje, mora povrniti, kdor je zažgal.',
        7: 'Če kdo shrani pri svojem prijatelju denar ali blago, in bode ukradeno iz hiše tega moža: ako se tat najde, mora dvojno povrniti;',
        8: 'ako tatu ne najdejo, naj se postavi hišni gospodar pred sodnike, ni li iztegnil roke svoje po blagu bližnjega svojega.',
        9: 'Ob vsakem poneverjenju, če gre za vola, ali osla, ali ovco, ali obleko ali za katerokoli izgubljeno reč, o kateri se pravi: Moja je, naj pride pravda obeh strank pred sodnike: kogar sodniki spoznajo za krivega, ta naj dvojno plača bližnjemu svojemu.',
        10: 'Če kdo shrani pri svojem sosedu osla ali vola ali ovco ali kako drugo žival, in ta pogine ali bode poškodovana ali odpeljana, ne da bi kdo videl to:',
        11: 'prisega Gospodova naj odloči med njima, ni li iztegnil roke svoje po blagu bližnjega svojega, in lastnik njegov jo sprejme, in oni ne bo dolžan povrniti.',
        12: 'Ako pa mu je bilo ukradeno, naj povrne lastniku.',
        13: 'Če je zver raztrgala živinče, naj to prinese v potrdilo; raztrganega mu ni treba povrniti.',
        14: 'In če si kdo izposodi od svojega bližnjega živino, in bode poškodovana ali pogine v nenavzočnosti gospodarjevi, mu jo mora povrniti,',
        15: 'ako pa je gospodar zraven, mu je ne povrne: najeta je bila, in vštelo se je v najemščino.',
        16: 'Če kdo zapelje devico, ki ni še zaročena, in leži ž njo, mora plačati doto in si jo vzeti za ženo.',
        17: 'Če mu je pa njen oče nikakor noče dati, naj odšteje denarja primerno doti, navadni za device.',
        18: 'Čarovnici ne daj živeti.',
        19: 'Kdorkoli leži z živino, mora umreti.',
        20: 'Kdor daruje bogovom mimo samega Gospoda, bodi iztrebljen.',
        21: 'Tujcu ne delaj sile in ga ne tlači, kajti tujci ste bili v deželi Egiptovski.',
        22: 'Nobene vdove in sirote ne žalite.',
        23: 'Če jih kakorkoli razžališ in bodo vpile k meni, gotovo uslišim njih vpitje;',
        24: 'in razvname se jeza moja, in vas pomorim z mečem, da bodo žene vaše vdove in otroci vaši sirote.',
        25: 'Če denarja posodiš ljudstvu mojemu, ubožcu, ki biva zraven tebe, ne bodi mu kakor oderuh, tudi mu ne naloži obresti.',
        26: 'Če sploh prejmeš plašč bližnjega svojega v zastavo, povrni mu ga, preden solnce zaide;',
        27: 'kajti to je edina odeja njegova, obleka za nagoto njegovo: v čem naj bi spal? In zgodi se, če bo vpil k meni, da ga uslišim, kajti jaz sem milostljiv.',
        28: 'Sodnikov ne kolni in kneza ljudstva svojega ne preklinjaj.',
        29: 'Ne odlašaj darovati od obilosti žita svojega in tekočine svoje. Prvenca izmed sinov svojih daruj meni.',
        30: 'Enako delaj z govedjo in drobnico svojo: sedem dni naj ostane pri materi svoji, osmi dan jo pa daruj meni.',
        31: 'In sveti možje mi bodite; zato mesa, ki je na polju raztrgano od zveri, ne jejte, temuč ga vrzite psom.',
    },
    23: {
        1: 'Ne raznašaj lažnivega govorjenja; ne podajaj roke svoje krivičniku, da bodeš priča za nepravičnost.',
        2: 'Ne potegni z množico, da bi delal zlo; in v pravdi ne govóri iz nagnjenja do množice, da se izprevrne sodba.',
        3: 'Tudi na ubožca se ne oziraj v pravdi njegovi.',
        4: 'Ako srečaš vola sovražnika svojega ali osla, da je zašel, pripelji mu ga varno nazaj.',
        5: 'Ako vidiš osla sovražilca svojega, da leži pod tovorom svojim, ne hodi mimo, ne da bi mu pomagal: rad mu pomozi ž njim vred.',
        6: 'Ne zavijaj pravice siromaku svojemu v pravdi njegovi.',
        7: 'Ogiblji se nepoštene reči. Nedolžnega in pravičnega ne ubijaj, zakaj krivičnega ne opravičim.',
        8: 'Ne jemlji daril, kajti darilo oslepi nje, ki gledajo z odprtimi očmi, in preobrne besede pravičnih.',
        9: 'In tujca ne tlači, zakaj veste, kako je v duši tujcu, ker ste sami bili tujci v deželi Egiptovski.',
        10: 'Šest let posevaj zemljo svojo in spravljaj pridelke njene;',
        11: 'a sedmo leto naj ti leži in počiva, da jo uživajo ubožci tvojega ljudstva, in kar po njih preostane, naj pojé poljska zverina. Prav tako delaj z vinogradom in z olivnikom svojim.',
        12: 'Šest dni opravljaj posel svoj in sedmi dan počivaj, da se odpočijeta vol in osel tvoj in se oddahneta sin dekle tvoje in tujec.',
        13: 'In pazite na vse, kar sem vam rekel; in imena tujih bogov ne omenjajte, še sliši naj se ne iz vaših ust.',
        14: 'Trikrat v letu mi posvečuj praznik.',
        15: 'Praznik opresnikov praznuj: sedem dni boš jedel opresen kruh, kakor sem ti zapovedal, v določeni čas v mesecu Abibu, kajti v njem si šel iz Egipta; in nihče naj se ne prikaže prazen pred mojim obličjem;',
        16: 'in praznik žetve, prvin tvojega pridelka, tistega, kar seješ na polju; in praznik spravljanja ob koncu leta, kadar pospraviš svoje pridelke s polja.',
        17: 'Trikrat v letu naj se prikažejo vsi moški tvoji pred obličjem Gospoda Jehove.',
        18: 'Ne daruj krvi daritve moje zraven kvašenega kruha, in masti od mojega praznika naj ne ostane do jutra.',
        19: 'Prve prvine plodov zemlje svoje prinesi v hišo Gospoda, svojega Boga. Ne kuhaj kozliča v matere njegove mleku.',
        20: 'Glej, jaz pošiljam angela svojega pred teboj, da te varuje na potu in te pripelje v kraj, katerega sem pripravil.',
        21: 'Pazi se obličja njegovega in poslušaj njegov glas; ne upiraj se mu, ker ne izpregleda prestopkov vaših, zakaj moje ime je v njem.',
        22: 'Če boš pa pazljivo poslušal njegov glas in delal vse, kar govorim: sovražnik bodem tvojim sovražnikom in nasprotnikom tvojim nasprotnik.',
        23: 'Kajti angel moj pojde pred teboj in te privede k Amorejcem in Hetejcem in Ferizejcem in Kanaancem in Hevejcem in Jebusejcem, in jih iztrebim.',
        24: 'Ne klanjaj se njih bogovom in jim ne služi, tudi ne delaj po njih delih, marveč docela jih razruši in dočista poteri njih stebre s podobami.',
        25: 'In služite Gospodu, Bogu svojemu, in blagoslovil bo kruh tvoj in vodo tvojo, in odpravim bolezen izmed vas.',
        26: 'Ne bode je, ki bi negodno rodila, ne nerodovitne v deželi tvoji; število dni tvojih dopolnim.',
        27: 'Strah svoj pošljem pred teboj ter zbegam vsa ljudstva, h katerim prideš, in vse sovražnike tvoje poženem v beg pred teboj.',
        28: 'In pošljem pred teboj sršene, ki bodo pregnali Hevejce, Kanaance in Hetejce izpred tebe.',
        29: 'Ne preženem jih izpred tebe v enem letu, da se ne opustoši dežela in se ne pomnože poljske zveri zoper tebe.',
        30: 'Pomalem jih preženem izpred tebe, dokler se ne razmnožiš in ne posedeš dežele.',
        31: 'In postavim mejo tvojo od Rdečega morja do morja Filistejcev in od puščave do velereke; kajti v roko tvojo dam prebivalce tiste dežele, in izgnal jih boš pred seboj.',
        32: 'Zaveze ne skleni ž njimi, ne ž njih bogovi.',
        33: 'Ne prebivajo naj v tvoji deželi, da te ne zapeljejo v greh zoper mene; zakaj če bi služil njih bogovom, bi ti gotovo bilo v zanko.',
    },
    24: {
        1: 'In Mojzesu je rekel: Pridi gori h Gospodu, ti in Aron, Nadab in Abihu in sedemdeset izmed starejšin Izraelovih, in molite oddaleč.',
        2: 'In Mojzes sam naj pristopi h Gospodu, oni pa naj ne pristopijo, in tudi ljudstvo naj ne hodi gori ž njim.',
        3: 'In Mojzes gre in pove ljudstvu vse besede Gospodove in vse sodne pravice; in vse ljudstvo odgovori z enim glasom, rekoč: Storiti hočemo vse besede, ki jih je govoril Gospod.',
        4: 'In Mojzes je napisal vse besede Gospodove. In vstane zgodaj zjutraj in sezida oltar pod goro in dvanajst kamenenih spomenikov po številu dvanajstih rodov Izraelovih.',
        5: 'In pošlje izmed Izraelovih otrok mladeniče, ki so darovali žgalne daritve in klali mirovne daritve juncev Gospodu.',
        6: 'In Mojzes vzame polovico krvi in jo dene v medenice, z drugo polovico krvi pa poškropi oltar.',
        7: 'In vzame knjigo zaveze in bere, da sliši ljudstvo. In rekli so: Storiti hočemo vse, kar je govoril Gospod, in pokorni bodemo.',
        8: 'In Mojzes vzame kri in poškropi ž njo ljudstvo in reče: Glejte, kri zaveze, ki jo je Gospod z vami sklenil na podlagi vseh teh besed.',
        9: 'Tedaj so šli gori Mojzes in Aron, Nadab in Abihu in sedemdeset izmed starejšin Izraelovih.',
        10: 'In videli so Boga Izraelovega: in pod njegovimi nogami je bilo kakor tla iz safirovih plošč in kakor nebo, kadar je jasno.',
        11: 'In ni iztegnil roke svoje zoper plemenitnike Izraelovih sinov, in videli so Boga in so jedli in pili.',
        12: 'In Gospod reče Mojzesu: Stopi k meni na goro in bodi tukaj; in dam ti kameniti plošči ter postavo in zapoved, katero sem napisal, da jih učiš.',
        13: 'Mojzes torej vstane in Jozue, strežnik njegov, in Mojzes stopi na goro Božjo.',
        14: 'Starejšinam pa je bil rekel: Ostanite tukaj, dokler se k vam ne povrneva; in glejte, Aron in Hur sta pri vas: če ima kdo kako reč, naj pride k njima.',
        15: 'In Mojzes stopi na goro, in oblak pokrije goro.',
        16: 'In slava Gospodova je počivala na gori Sinajski, in oblak jo je pokrival šest dni; in sedmi dan je poklical Mojzesa iz sredi oblaka.',
        17: 'In kazala se je slava Gospodova kakor požirajoč ogenj na vrhu gore pred očmi sinov Izraelovih.',
        18: 'In Mojzes je šel v sredo oblaka in stopil na goro; in bil je Mojzes na gori štirideset dni in štirideset noči.',
    },
    25: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Véli sinovom Izraelovim, naj mi prineso dar povzdignjenja; od vsakega, kogar izpodbode srce njegovo, vzemite dar povzdignjenja meni.',
        3: 'In to je dar povzdignjenja, ki ga jemljite od njih: zlato, srebro, bron,',
        4: 'višnjevo in zagorelordeče blago in karmezin in tenčica in kozja dlaka,',
        5: 'rdeče barvane ovnove kože in jazbečeve kože in akacijev les;',
        6: 'olje za svetilnice, dišave za mazilno olje in za dišeče kadilo;',
        7: 'onihovi kameni in drugi kameni, ki se vdenejo na naramnik in naprsnik.',
        8: 'In naredé naj mi svetišče, da bom prebival med njimi.',
        9: 'Kakor ti kažem vzorec prebivališča in vzorce vse oprave njegove, prav tako naredite.',
        10: 'Narede naj torej skrinjo iz akacijevega lesa: dva in pol komolca bodi nje dolgost, poldrugi komolec nje širjava in poldrugi komolec visokost njena.',
        11: 'In prevleci jo s čistim zlatom, odznotraj in odzunaj jo prevleci; in napravi vrhu nje zlat venec naokrog.',
        12: 'In zliješ zanjo štiri zlate obode in jih deneš na njene štiri noge: dva oboda bodeta na eni strani in dva oboda na drugi strani njeni.',
        13: 'In naredi dva droga iz akacijevega lesa in ju okuj z zlatom.',
        14: 'In vtakni ta droga v obode na obeh straneh skrinje, da se skrinja prenaša ž njima.',
        15: 'Droga naj ostaneta v obodih skrinje, ne smeta se odstraniti iz njih.',
        16: 'V skrinjo pa deni pričevanje, ki ti ga dam.',
        17: 'In naredi pokrov sprave iz čistega zlata: dva in pol komolca bodi dolg in poldrugi komolec širok.',
        18: 'Naredi tudi dva kerubima iz zlata; s tolkljanim delom ju naredi na obeh koncih spravnega pokrova:',
        19: 'enega keruba na tej strani in enega na drugi strani, sceloma s spravnim pokrovom naredi keruba na obeh koncih njegovih.',
        20: 'In keruba naj razprostirata peruti navzgor, zaslanjajoč s svojimi perutmi pokrov, z obrazoma drug proti drugemu; proti pokrovu sprave bodita obrnjeni obličji kerubov.',
        21: 'In deni pokrov sprave na vrh skrinje, in v skrinjo deni pričevanje, katero ti dam.',
        22: 'In tam se bom shajal s teboj in ti govoril iznad spravnega pokrova, iz sredi dveh kerubov, ki sta na skrinji pričevanja, vse, kar ti bom zapovedoval za sinove Izraelove.',
        23: 'Naredi tudi mizo iz akacijevega lesa: dva komolca bodi dolga in en komolec široka in poldrugi komolec visoka.',
        24: 'In prevleci jo s čistim zlatom in napravi na njej zlat venec naokrog.',
        25: 'In naredi k njej kroginkrog spojno deščico, za dlan široko, in napravi zlat venec tej deščici naokrog.',
        26: 'In naredi zanjo štiri roče iz zlata in deni te roče na štiri vogle pri štirih njenih nogah.',
        27: 'Tik pod deščico naj bodo roči, da se vanje vtakneta droga, s katerima se bo prenašala miza.',
        28: 'In droga naredi iz akacijevega lesa in ju okuj z zlatom, in ž njima naj se prenaša miza.',
        29: 'In naredi zanjo sklede, torila, konvice in vrčke, s katerimi se bo izlivalo; iz čistega zlata jih naredi.',
        30: 'In položi na mizo kruhe obličja, ki naj bodo pred obličjem mojim neprestano.',
        31: 'Napravi tudi svečnik iz čistega zlata: s tolkljanim delom naj ga narede, stojalo in deblo njegovo; čašice, glavice in cvetice njegove naj bodo sceloma delane ž njim.',
        32: 'In šest vej naj se razpenja iz debla njegovega: tri veje od ene strani in tri veje od druge strani svečnika.',
        33: 'Tri čašice, slične mandeljnovemu cvetu, naj bodo z glavico in cvetico na eni veji, in prav enako na veji drugi; in tako bodi na šesterih vejah, ki se razpenjajo iz svečnika.',
        34: 'Na svečnikovem deblu pa naj bodo štiri čaše, slične mandeljnovemu cvetu, s svojimi glavicami in cveticami,',
        35: 'namreč ena glavica pod vsakima dvema vejama, ki se jih razpenja šest iz ene celote, iz svečnika.',
        36: 'Njegove glavice in veje morajo biti ena celota ž njim, vse bodi enotno tolkljano delo, iz zlata čistega.',
        37: 'In njegovih svetilnic naredi sedem; in prižgo naj svetilnice njegove, da svetijo prav v ospredje njegovo.',
        38: 'Njegova utrinjala in lončki za utrinke naj bodo iz čistega zlata.',
        39: 'Iz enega talenta čistega zlata bodi narejen z vsemi temi pripravami.',
        40: 'Glej pa, da narediš vse reči po njih vzorcu, ki ti je bil pokazan na gori.',
    },
    26: {
        1: 'In naredi prebivališče iz desetih preprog; iz sukane tenčice in iz višnjevega in zagorelordečega in karmezinovega blaga, s kerubi umetno pretkane jih narediš.',
        2: 'Dolgost preproge bodi osemindvajset komolcev, širjava pa štiri komolce: ista mera bodi vsem preprogam.',
        3: 'Pet preprog naj se zveže skupaj, tudi pet drugih preprog naj se stakne skupaj.',
        4: 'In naredi pentlje iz višnjeve preje na robu ene preproge, ob kraju ene zveze, enako naredi tudi na robu druge preproge, ob kraju druge zveze.',
        5: 'Petdeset pentelj napravi na prvi preprogi in petdeset pentelj napravi na robu druge preproge, kjer se bo vezala s prvo; pentlja bodi pentlji nasproti.',
        6: 'In naredi petdeset zapon iz zlata in stakni preprogi drugo z drugo s temi zaponami, da bode prebivališče celota.',
        7: 'In naredi preproge iz kozje dlake, da bodo šator nad prebivališčem; enajst takih preprog narediš.',
        8: 'Dolgost ene preproge bodi trideset komolcev, širjava pa štiri komolce: isto mero imej enajstero preprog.',
        9: 'In stakni pet preprog posebe in šest preprog posebe, šesto preprogo pa dvojno podviješ v pročelju šatora.',
        10: 'In naredi petdeset pentelj na robu skrajne preproge pri prvi zvezi in petdeset pentelj na robu preproge pri drugi zvezi.',
        11: 'In napravi petdeset bronastih zapon in vtakni te zapone v pentlje in spóji šator, da bo celota.',
        12: 'Glede tega pa, kar je prebitka šatorovih preprog: polovica preproge, ki preostaja, naj visi čez zadnjo stran šatora;',
        13: 'in tisti komolec ob eni strani in komolec ob drugi strani, ki sta odveč po dolgosti šatorovih preprog, naj visita čez obe strani prebivališča, da ga pokrivata.',
        14: 'In napravi odejo za šator iz rdečih ovnovih kož in odejo iz jazbečevih kož vrhu nje.',
        15: 'In naredi deske za prebivališče iz akacijevega lesa, pokonci stoječe:',
        16: 'deset komolcev bodi dolga vsaka deska, eden in pol komolca pa široka;',
        17: 'dva čepa imej vsaka deska spodaj, drug proti drugemu vstavljena: tako napravi pri vseh deskah prebivališča.',
        18: 'In narediš deske za prebivališče, dvajset desek bodi za poldansko stran, proti jugu;',
        19: 'in štirideset podstav naredi pod dvajset desek: dve podstavi pod eno desko za dva čepa njena in dve podstavi pod drugo desko za dva čepa njena.',
        20: 'Na drugi strani prebivališča, na severni strani, bodi tudi dvajset desek',
        21: 'in zanje štirideset podstav srebrnih: dve podstavi pod eno desko in dve podstavi pod drugo desko.',
        22: 'In na zadnji strani prebivališča, proti zahodu, naredi šest desek;',
        23: 'in dve deski naredi za vogla prebivališču ob zadnji strani;',
        24: 'in bodeta naj dvojni odspodaj in enako naj bodeta skupaj sklenjeni ob vrhu svojem v enem obodu: tako naj bode pri obeh dveh, na obeh voglih naj bodeta.',
        25: 'Bode torej osem desek in njih srebrnih podstav šestnajst, dve podstavi pod vsako desko.',
        26: 'In narédi zapahe iz akacijevega lesa: pet za deske na eni strani prebivališča',
        27: 'in pet zapahov za deske na drugi strani prebivališča in pet za deske na zadnji strani prebivališča, proti zahodu;',
        28: 'in srednji zapah sredi desek naj sega od konca do konca.',
        29: 'In deske prevleci z zlatom, in njih obode, namreč shrambice za zapahe, napravi iz zlata in zapahe okuj z zlatom.',
        30: 'In tako postavi prebivališče, po predpisu, ki ti je bil pokazan na gori.',
        31: 'In narédi zagrinjalo iz višnjevega in zagorelordečega in karmezinovega blaga in iz sukane tenčice; umetno tkano bodi, s podobami kerubov;',
        32: 'in obesi ga na štiri stebre iz akacijevega lesa, prevlečene z zlatom; njih kavlji naj bodo iz zlata, in stoje naj na štirih podstavah iz srebra.',
        33: 'Obesi pa zagrinjalo pod zapone preprog in ponesi tja, noter za zagrinjalo, skrinjo pričevanja. In zagrinjalo vam bo ločilo Sveto od Najsvetejšega.',
        34: 'In deni pokrov sprave na skrinjo pričevanja v Najsvetejšem.',
        35: 'Mizo pa postavi zunaj zagrinjala in svečnik mizi nasproti, na stran prebivališča proti jugu; mizo namreč postaviš na severno stran.',
        36: 'In za vhod v šator naredi zaveso iz višnjevega in zagorelordečega blaga in iz karmezina in sukane tenčice, z umetno pisanim vezenjem.',
        37: 'In za zaveso napravi pet stebrov iz akacijevega lesa in jih okuj z zlatom; njih kavlji naj bodo iz zlata, in ulij zanje pet podstav iz brona.',
    },
    27: {
        1: 'In naredi oltar iz akacijevega lesa, pet komolcev dolg in pet komolcev širok – četverokoten bodi oltar – in tri komolce visok.',
        2: 'In naredi mu štiri rogove na štirih voglih njegovih, sceloma naj bodo delani ž njim tisti rogovi, in okuj ga z bronom.',
        3: 'In naredi zanj pepelnjake in lopate in čaše in vilice in ponve za žerjavico: vse priprave njegove napravi iz brona.',
        4: 'In naredi zanj bronasto omrežje, mrežastega dela, in na omrežju napravi štiri bronaste obode na štirih voglih njegovih;',
        5: 'in postavi ga k obrobnemu podstavku oltarja, odspodaj, da seže omrežje do polovice oltarja.',
        6: 'In naredi droga za oltar, droga iz akacijevega lesa, in ju okuj z bronom.',
        7: 'In droga njegova naj se vtakneta v obode, da bosta droga na obeh straneh oltarja, ko ga bodo prenašali.',
        8: 'Votlega, iz desek ga naredi; kakor ti je bilo pokazano na gori, tako naj ga napravijo.',
        9: 'Naredi tudi prebivališču dvorišče: na poldanski strani, proti jugu, naj bodo zastori iz sukane tenčice, sto komolcev dolgi na eni strani;',
        10: 'in njih stebrov bodi dvajset, tudi njih bronastih podstavkov dvajset; kavlji za stebre in njih vezila naj bodo iz srebra.',
        11: 'In ravno tako na severni strani, po dolgosti, bodo zastori sto komolcev dolgi, in zanje dvajset stebrov in dvajset podstavkov iz brona, kavlji za stebre in njih vezila iz srebra.',
        12: 'Po širjavi dvorišča, na zahodni strani, pa bodi petdeset komolcev zastorov, njih stebrov deset in njih podstavkov deset.',
        13: 'In širjava dvorišču na vzhodni strani bodi petdeset komolcev;',
        14: 'petnajst komolcev zastorov ob eni strani vhoda, in njih stebrov troje in njih podstavkov troje;',
        15: 'tudi ob drugi strani vhoda petnajst komolcev zastorov, trije stebri in trije podstavki.',
        16: 'In za vrata na dvorišče bodi zavesa dvajsetih komolcev iz višnjevega in zagorelordečega blaga in iz karmezina in sukane tenčice, umetno pisano vezenje, in njeni stebri štirje in podstavki štirje.',
        17: 'Za vse stebre krog dvorišča naj se napravijo srebrna vezila, tudi njih kavlji bodo iz srebra, njih podstavki pa iz brona.',
        18: 'Dolgost dvorišča bode sto komolcev, širjava pa petdeset z obeh strani, pet komolcev pa visokost zastorov iz sukane tenčice, in njih podstavki iz brona.',
        19: 'Vse priprave prebivališča za vso službo pri njem in vsi kolčki njegovi in vsi kolčki ob dvorišču naj bodo iz brona.',
        20: 'Ti pa zapovej sinovom Izraelovim, da ti prineso čistega oljkovega olja, z betom iztolčenega, za svetilo, da se prižigajo svetilnice neprestano.',
        21: 'V shodnem šatoru, zunaj zagrinjala, ki je razpeto pred pričevanjem, naj jih pripravljajo Aron in sinovi njegovi, da goré od večera do jutra pred Gospodom. Večna postava bodi to za njih rodove, ki naj jo izpolnjujejo sinovi Izraelovi.',
    },
    28: {
        1: 'Ti pa vzemi k sebi Arona, brata svojega, in sinove njegove ž njim, izmed Izraelovih otrok, da mi služi kot duhovnik Aron, Nadab in Abihu, Eleazar in Itamar, sinovi Aronovi.',
        2: 'In naredi Aronu, bratu svojemu, sveta oblačila, za čast in za kras.',
        3: 'In ti govori z vsemi, ki so modrega srca, katere sem napolnil z duhom modrosti, naj napravijo Aronu oblačila, da bo posvečen v službo duhovniško meni.',
        4: 'In ta so oblačila, ki jih izgotovijo: naprsnik, naramnik, vrhnja suknja in spodnja iz stanične tkanine, pokrivalo in pas; in narede sveta oblačila Aronu, bratu tvojemu, in sinovom njegovim, da služi meni za duhovnika.',
        5: 'In naj za to porabijo zlato, višnjevo in zagorelordeče blago in karmezin in tenčico.',
        6: 'Narede pa naj naramnik iz zlata, iz višnjevega in zagorelordečega blaga, iz karmezina in sukane tenčice, umetno tkano delo.',
        7: 'Naj ima dva obramna dela, ki se zgoraj na koncih sklepata, da sta v eno.',
        8: 'In umetno tkana preveza na njem, s katero se bo privezoval, enega dela bodi ž njim in iz istega blaga: iz zlata, višnjeve in zagorelordeče preje, karmezina in sukane tenčice.',
        9: 'In vzemi dva onihova kamena in vreži vanju imena sinov Izraelovih:',
        10: 'šest njih imen na en kamen in šest drugih na drugi kamen, po redu njih rojstva.',
        11: 'Kamenorisarsko delo bodi, kakor se vrezuje v pečate; na oba kamena daj vrezati imena sinov Izraelovih; in opleti ju s pletežem iz zlata.',
        12: 'In priklopi oba kamena na obramna dela naramnikova, da bodeta kamena spomina na sinove Izraelove; in Aron naj nosi njih imena pred Gospodom na obeh ramah svojih v spomin.',
        13: 'In narédi okove iz zlata',
        14: 'in dve verižici iz čistega zlata, kakor vrvi ju napravi, s pletenjem, in tisti pleteni verižici pritakni k okovom.',
        15: 'In napravi naprsnik sodbe, umetno tkano delo bodi kakor naramnik, iz zlata, iz višnjevega in zagorelordečega blaga, iz karmezina in sukane tenčice.',
        16: 'Štirivoglat naj bode in v dve gubi, pedenj dolg in pedenj širok.',
        17: 'In obloži ga z okovanimi kameni, v štirih vrstah: sardij, topaz in smaragd bodi prva vrsta;',
        18: 'druga vrsta pa: rubin, safir in diamant;',
        19: 'tretja vrsta: hiacint, ahat in ametist;',
        20: 'četrta vrsta: krizolit, onih in jaspis; obdani naj bodo z zlatom v svojih vrstah.',
        21: 'Primerno imenom sinov Izraelovih naj bode dvanajst kamenov, in na vsakem kamenu bodi vrezano po eno ime izmed dvanajsterih rodov, s pečatarjevim delom.',
        22: 'In narédi za naprsnik vrvčasti verižici, spleteni iz čistega zlata;',
        23: 'in naredi dva zlata obročka k naprsniku in ju pritakni na oba konca njegova;',
        24: 'in pritrdi tisti dve spleteni zlati verižici v dva obročka na obeh koncih naprsnika;',
        25: 'in druga dva konca obeh spletenih verižic zapni v obadva okova in ju pritakni na obramna dela naramnikova, spredaj.',
        26: 'In naredi dva druga obročka iz zlata in ju pritakni na druga dva konca naprsnikova, na rob, ki je proti naramniku, odznotraj.',
        27: 'Naredi še dva obročka iz zlata in ju prikleni na oba obramna dela naramnikova spodaj ob sprednji strani, ravno tam, kjer se sklepa, vrhu umetno tkane preveze naramnikove.',
        28: 'In privežejo naj naprsnik, njegove obročke k naramnikovim obročkom z višnjevo vrvico, da se gladko prilega nad umetno tkano prevezo naramnikovo ter da se naprsnik ne premakne raz naramnik.',
        29: 'In Aron naj nosi imena sinov Izraelovih na naprsniku sodbe na srcu svojem, kadar pojde v svetišče, v spomin pred Gospodom vselej.',
        30: 'In v naprsnik sodbe deni Urim in Tumim, da bodeta na srcu Aronovem, kadar pojde pred obličje Gospodovo; in Aron naj nosi sodbo sinom Izraelovim, na srcu svojem pred Gospodom vselej.',
        31: 'In naredi vrhnjo suknjo pod naramnik iz višnjevega blaga.',
        32: 'In zgoraj sredi nje bodi odprtina, in tkano tvestje naj ima okoli odprtine, da bode odprtina kakor pri oklepu, da se ne razdere.',
        33: 'Spodaj okoli roba pa naredi margaranovih jabolk iz višnjevega, zagorelordečega blaga in iz karmezina, kroginkrog po njenem robu, in mednje zlate zvončke vseokoli:',
        34: 'da je zlat zvonček in margaranovo jabolko, in zopet zlat zvonček in margaranovo jabolko na robu suknje vseokoli.',
        35: 'In Aron jo imej na sebi za službo, da se sliši zvončkanje njegovo, kadar gre v svetišče pred obličje Gospodovo in kadar stopa ven, da ne umrje.',
        36: 'In napravi ploščo iz čistega zlata in vreži vanjo, kakor se vrezuje v pečate: SVETOST Gospodu!',
        37: 'in priveži jo z višnjevo prevezo, da bode na pokrivalu; spredaj bodi na pokrivalu.',
        38: 'In bode na čelu Aronovem, in Aron bo nosil svetih reči krivico, ki je na vseh svetih darilih, katera posvečujejo Izraelovi sinovi; in bode na čelu njegovem vedno, da jih stori blagougodne obličju Gospodovemu.',
        39: 'In narédi spodnjo suknjo iz tenčice, staničastega tkanja; in naredi pokrivalo iz tenčice, in pas naredi z vezilnim delom.',
        40: 'In sinovom Aronovim naredi spodnje suknje in pase in visoke čepice, njim v čast in kras.',
        41: 'In obleci vanje Arona, brata svojega, in sinove njegove ž njim vred; in pomazili jih ter jim napolni roke in jih posveti, da mi opravljajo duhovsko službo.',
        42: 'Napravi jim tudi platnene hlače, da zakrijejo meso sramote svoje: od ledij do stegen naj segajo.',
        43: 'In Aron in sinovi njegovi naj jih imajo na sebi, kadar gredo v shodni šator ali kadar se bližajo oltarju, opravljat službo v svetišču, da si ne naložijo krivde in ne umro: večna to bodi postava njemu in semenu njegovemu za njim.',
    },
    29: {
        1: 'To pa je, kar jim storiš, da jih posvetiš, da bi mi opravljali duhovsko službo. Vzemi mladega junca in dva ovna brez madeža',
        2: 'in nekvašenega kruha in opresnih kolačev, z oljem zamešenih, in opresnih mlincev, z oljem pomazanih; iz čiste pšenične moke jih pripravi.',
        3: 'V en koš jih deni in jih prinesi v košu, in junca in dva ovna.',
        4: 'Arona pa in njegove sinove privedeš k vhodu v shodni šator ter jih umiješ z vodo.',
        5: 'Nato vzemi oblačila in obleci Arona v spodnjo suknjo in vrhnjo naramnikovo suknjo in naramnik in naprsnik in ga prepaši z umetno tkano naramnikovo prevezo.',
        6: 'In mu deni pokrivalo na glavo in priveži zlati venec na pokrivalo.',
        7: 'In vzemi mazilnega olja in ga izlij na glavo njegovo ter ga pomazili.',
        8: 'Tudi sinove njegove pripelji in jih obleci v spodnje suknje.',
        9: 'In opaši jih s pasovi, Arona in sinove njegove, ter jim priveži visoke čepice; in bode jim duhovništvo po večni postavi. In napolniš roke Aronu in sinom njegovim v posvečenje.',
        10: 'In pripelji junca pred shodni šator, in Aron in sinovi njegovi naj polože roke svoje juncu na glavo.',
        11: 'In zakolji junca pred Gospodom ob vhodu v shodni šator',
        12: 'ter vzemi junčeve krvi in jo deni s prstom na rogove oltarja, vso drugo kri pa izlij spodaj ob oltarju.',
        13: 'In vzemi vso tolstino, ki pokriva drobje, in pečico na jetrih in obe ledici s tolstjo, ki je na njiju, in zažgi to na oltarju.',
        14: 'Ali junčevo meso in kožo in iztrebke njegove sežgi z ognjem zunaj šatorišča: daritev za greh je.',
        15: 'Nato vzameš enega ovna, in Aron in sinovi njegovi naj mu polože roke svoje na glavo.',
        16: 'In zakolji ovna ter vzemi krvi njegove in škropi ž njo okrog po oltarju.',
        17: 'Ovna pa razreži na kose, in operi drob njegov in stegna njegova ter jih položi na kose njegove in na glavo njegovo.',
        18: 'In zažgi vsega ovna na oltarju: žgalna žrtev je Gospodu, prijeten duh, daritev po ognju Gospodu.',
        19: 'Potem vzemi drugega ovna, in Aron in sinovi njegovi naj mu polože roke svoje na glavo.',
        20: 'In zakolji ovna ter vzemi krvi njegove in jo deni na mečico desnega ušesa Aronovega in na mečico desnega ušesa sinov njegovih in na palec njih desnice in na palec desne noge; ostalo kri pa razškropi po oltarju okoli.',
        21: 'In vzemi krvi, ki je na oltarju, in mazilnega olja ter pokropi Arona in oblačila njegova in sinove njegove in oblačila sinov njegovih ž njim vred; in posvečen bode in oblačila njegova in sinovi njegovi in sinov njegovih oblačila ž njim vred.',
        22: 'Vzemi tudi tolstine ovnove in tolsti rep in tolst, ki pokriva drob, in pečico na jetrih in obe ledici in tolst, ki je na njiju, in desno stegno (kajti je oven posvečenja)',
        23: 'in hleb kruha in kolač z oljem zamešanega kruha in mlinec iz koša opresnikov, ki je pred Gospodom,',
        24: 'in položi vse to na roke Aronu in sinom njegovim, in majaj to kot daritev majanja pred Gospodom.',
        25: 'Potem vzemi to iz njih rok ter zažgi na oltarju vrhu žgalne daritve v prijeten duh pred Gospodom; ognjena daritev je Gospodu.',
        26: 'In vzemi prsi od ovna posvetitve, ki je za Arona, ter jih daruj z majanjem pred Gospodom; in bodo tebi v delež.',
        27: 'In posvetiš prsi daritve majanja, ki so se majale, in stegno povzdignjenja, ki se je povzdignilo od ovna posvetitve, ki je za Arona in za sinove njegove;',
        28: 'in dobi naj to Aron in sinovi njegovi kot vekomaj sebi določeno od sinov Izraelovih, kajti dar povzdignjenja je; in bode to dar povzdignjenja od sinov Izraelovih, od njih mirovnih daritev, njih dar povzdignjenja Gospodu.',
        29: 'Sveta oblačila Aronova pa bodo za sinove njegove za njim, da bodo v njih maziljeni ter da se jim v njih napolnijo roke v posvečenje.',
        30: 'Sedem dni jih bo oblačil tisti iz sinov njegovih, ki bode duhovnik na mestu njegovem, ko pojde v šator pričevanja služit v svetišču.',
        31: 'Ovna posvetitve pa vzemi in skuhaj meso njegovo na svetem kraju.',
        32: 'In Aron in sinovi njegovi naj jedo meso ovnovo in kruh, ki je v košu, ob vhodu v shodni šator:',
        33: 'jedo naj tiste reči, po katerih se je izvršila poravnava, da bi se jim napolnile roke, da bodo posvečeni; tujec pa jih ne sme jesti, ker so svete.',
        34: 'Ako pa ostane do jutra kaj mesa posvetitve in kruha, naj se sežge, kar je ostalo; ne sme se jesti, ker je sveto.',
        35: 'Stóri torej Aronu in sinom njegovim natanko po vsem, kar sem ti zapovedal. Sedem dni jim napolnjuj roke v posvetitev.',
        36: 'In vsak dan daruj v poravnavo junca kot daritev za greh, in očistiš oltar greha, ko storiš poravnavo zanj; in ga pomazili, da ga posvetiš.',
        37: 'Sedem dni opravljaj poravnavo za oltar in ga posvečuj; in oltar bodi presvet: karkoli se dotakne oltarja, bode sveto.',
        38: 'To pa je, kar boš pripravljal na oltar: vsak dan dve jagnjeti, po eno leto stari, neprenehoma.',
        39: 'Eno jagnje daruj zjutraj, drugo jagnje proti večeru;',
        40: 'in k prvemu jagnjetu desetinko bele moke, zmešane s četrtino hina iztolčenega olja, in četrtino hina vina kot pitno darilo.',
        41: 'In drugo jagnje pripravi proti večeru; zastran jedilnega in pitnega darila ravnaj po jutranjem darovanju: v prijeten duh bodi, ognjena daritev Gospodu.',
        42: 'To bodi neprestana žgalna daritev po rodovih vaših pri vhodu shodnega šatora pred Gospodom, kjer se bom shajal z vami, da govorim s teboj.',
        43: 'In tam se bom shajal s sinovi Izraelovimi, in šator bo posvečen po slavi moji.',
        44: 'In posvetim shodni šator in oltar, tudi Arona in sinove njegove posvetim, da mi opravljajo duhovsko službo.',
        45: 'In prebival bom sredi sinov Izraelovih in jim bodem Bog.',
        46: 'In spoznajo, da sem jaz Gospod, njih Bog, ki sem jih odpeljal iz dežele Egiptovske, da bi prebival sredi njih. Jaz sem Gospod, njih Bog.',
    },
    30: {
        1: 'Naredi tudi oltar, na katerem se bo zažigalo kadilo; iz akacijevega lesa ga napravi:',
        2: 'komolec bodi dolg, komolec širok, štirivoglat naj bo, in dva komolca visok; iz ene celote ž njim naj bodo rogovi njegovi.',
        3: 'In prevleci ga s čistim zlatom, njegov vrh in njegove stene kroginkrog in njegove rogove; in napravi mu zlat venec naokrog.',
        4: 'In naredi mu dva zlata oboda pod vencem njegovim, ob voglih njegovih na obeh straneh, da se vanju vtakneta droga, ki se bo nosil ž njima.',
        5: 'Droga pa tudi naredi iz akacijevega lesa in ju prevleci z zlatom.',
        6: 'In oltar postavi nasproti zagrinjalu, ki visi pred skrinjo pričevanja, in nasproti pokrovu sprave, ki je vrhu pričevanja, kjer se bom shajal s teboj.',
        7: 'In Aron naj zažiga na njem blagodišeče kadilo; vsako jutro, ko pripravlja svetilnice, naj zakadi.',
        8: 'Tudi ko prižiga svetilnice proti večeru, naj zakadi: neprestano bodi kadilo pred Gospodom po rodovih vaših.',
        9: 'Ne smete na njem darovati tujega kadila, ne žgalščine, ne jedilne daritve, tudi pitne daritve ne izlijte nanj.',
        10: 'A enkrat v letu naj opravi Aron poravnavo na rogovih njegovih s krvjo daritve za greh, ki je v spravo; enkrat v letu naj stori zanj poravnavo po prihodnjih rodovih vaših: presvet je Gospodu.',
        11: 'In Gospod je govoril Mojzesu, rekoč:',
        12: 'Ko poizveš število sinov Izraelovih, kolikor jih gre v štetje, tedaj naj plača vsakdo odkupnino za dušo svojo Gospodu, kadar jih boš štel, da ne pride nadnje šiba, ko bodo šteti.',
        13: 'To naj dado: vsakdo, ki preide k preštetim, pol sekla, po seklu svetišča (dvajset ger ima sekel), pol sekla kot dar povzdignjenja Gospodu.',
        14: 'Sleherni, ki preide k preštetim, dvajset let star in več, naj da Gospodu dar povzdignjenja.',
        15: 'Bogatin ne da več in ubožec ne manj nego pol sekla, ko poklonite dar povzdignjenja Gospodu, da se stori poravnava za duše vaše.',
        16: 'In vzemi spravni denar od sinov Izraelovih ter ga obrni v službo v shodnem šatoru, da bodi to v spomin sinom Izraelovim pred Gospodom, v poravnavo za duše vaše.',
        17: 'Še je govoril Gospod Mojzesu, rekoč:',
        18: 'Naredi tudi bronast umivalnik z bronastim stojalom za umivanje in ga postavi med shodni šator in oltar in vlij vanj vode.',
        19: 'In Aron in sinovi njegovi naj si iz njega umivajo roke in noge:',
        20: 'kadar pojdejo v shodni šator, naj se umijejo z vodo, da ne umrjo, ali pa ko se bližajo oltarju služit, da zažgo ognjeno daritev Gospodu.',
        21: 'Umivajo pa naj si roke in noge, da ne umrjo. To jim bodi večna postava, njemu in semenu njegovemu od roda do roda.',
        22: 'Dalje je govoril Gospod Mojzesu, rekoč:',
        23: 'Ti pa si vzemi najboljših dišav: petsto seklov mire, ki teče sama od sebe, in polovico sladke skorje, namreč dvesto in petdeset, in dvesto in petdeset dišečega trstja',
        24: 'in kasije petsto, po seklu svetišča, in oljkovega olja mero hin;',
        25: 'in naredi iz tega olje za sveto maziljenje, mešano dišavje po mazilarjevi umetnosti: sveto mazilno olje bodi.',
        26: 'In pomazili ž njim shodni šator in skrinjo pričevanja,',
        27: 'mizo z vsemi posodami njenimi, svečnik s pripravo njegovo in kadilni oltar',
        28: 'in oltar za žgalščine z vsemi pripravami njegovimi in umivalnik in stojalo njegovo.',
        29: 'In tako jih posveti, in bodo presvete: karkoli se jih dotakne, bode sveto.',
        30: 'In pomazili Arona in sinove njegove ter jih posveti, da mi služijo za duhovnike.',
        31: 'Sinom Izraelovim pa govori in reci: To mi bodi sveto mazilno olje po prihodnjih rodovih vaših.',
        32: 'Na meso človeško se ne sme izliti, in po njega sestavi ne narejajte podobnega: sveto je, sveto vam bodi.',
        33: 'Kdor ga ponaredi ali kdor od njega da tujcu, bodi iztrebljen iz ljudstva svojega.',
        34: 'In Gospod je velel Mojzesu: Vzemi si dišav: dišeče smole, kadilne školjke, galbana, sladkih vonjav in prečiščenega kadila, vsakega enako težo,',
        35: 'in naredi iz tega kadilo, dišečino, po mazilarjevi umetnosti, osoljeno, čisto, sveto.',
        36: 'In stolci nekoliko v prah in ga deni pred pričevanje v shodni šator, kjer se bom shajal s teboj; presveto vam bodi.',
        37: 'In kadila, kakršnega napraviš, sebi po isti sestavi ne narejajte; za sveto Gospodu naj ti velja.',
        38: 'Kdor ga ponaredi, da bi ga duhal, bodi iztrebljen iz ljudstva svojega.',
    },
    31: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Poglej, poklical sem po imenu Bezalela, sina Urija, sinu Hurovega, iz rodovine Judove,',
        3: 'in sem ga napolnil z duhom Božjim, ki se kaže v modrosti in razumnosti in znanosti in v vsakršni spretnosti,',
        4: 'da izumlja umetnine in izdeluje iz zlata in srebra in brona',
        5: 'in zna rezati kamene, da se denejo v okove, in izrezavati les in delati vsakovrstne izdelke.',
        6: 'In glej, dal sem mu tudi Oholiaba, sina Ahisamakovega, iz rodovine Danove; in modrost sem del v srce vsem, ki so modrega srca, da delajo vse, kar sem ti zapovedal:',
        7: 'šator shoda in skrinjo pričevanja in pokrov, ki je na njej, in vso šatorovo opravo',
        8: 'in mizo in vso posodo njeno in čisti svečnik in vse priprave njegove in kadilni oltar',
        9: 'in oltar za žgalščine z vsemi pripravami in umivalnik in stojalo njegovo;',
        10: 'službena oblačila in sveta oblačila za Arona duhovnika in oblačila sinov njegovih za duhovsko službo;',
        11: 'in mazilno olje in blagodišeče kadilo za svetišče: po vsem, kar sem ti zapovedal, naj delajo.',
        12: 'In Gospod je dejal Mojzesu, rekoč:',
        13: 'Ti pa govori sinom Izraelovim in reci: Sobote moje res spoštujte, ker znamenje so med menoj in med vami po prihodnjih rodovih vaših, da veste, da sem jaz Gospod, ki vas posvečujem.',
        14: 'Imejte torej v čislih dan počitka, ker je svet za vas; kdorkoli ga oskruni, mora umreti; kajti kdorkoli bi delal kako delo v njem, ta duša bo iztrebljena izmed ljudstva svojega.',
        15: 'Šest dni naj se opravlja delo, a dan sedmi je sobota slovesnega počitka, sveta Gospodu; kdorkoli opravlja kak posel sobotni dan, mora umreti.',
        16: 'Zato naj ohranijo sinovi Izraelovi soboto, da praznujejo počitek po prihodnjih rodovih svojih, kot večno zavezo.',
        17: 'Znamenje je to med menoj in med sinovi Izraelovimi na veke; zakaj v šestih dneh je naredil Gospod nebo in zemljo, dan sedmi pa je počival in se poživil.',
        18: 'In dal je Mojzesu, ko je nehal govoriti ž njim na gori Sinaju, dve plošči pričevanja, kameneni plošči, popisani s prstom Božjim.',
    },
    32: {
        1: 'In ko je videlo ljudstvo, da se Mojzes obotavlja priti z gore, se zbere množica k Aronu in ga ogovori: Vstani, naredi nam bogove, ki naj gredo pred nami; zakaj tistemu možu Mojzesu, ki nas je odpeljal iz dežele Egiptovske, ne vemo, kaj se mu je prigodilo.',
        2: 'In Aron jim veli: Izderite zlate obodce, ki so v ušesih žen vaših, sinov in hčer vaših, in jih prinesite k meni.',
        3: 'In odtrga vse ljudstvo obodce zlate, ki so jih imeli v ušesih, in jih prinesejo k Aronu.',
        4: 'On pa jih vzame iz njih rok in jih upodobi z dolbilom in napravi iz njih zlito tele. In reko: To je bog tvoj, o Izrael, ki te je pripeljal gori iz dežele Egiptovske.',
        5: 'In ko Aron to vidi, sezida oltar pred njim in razglasi, rekoč: Jutri bodi praznik Gospodu!',
        6: 'In zjutraj vstanejo zgodaj, in darovali so žgalne in prinesli mirovne daritve; in ljudstvo je sedlo jest in pit in vstalo igrat.',
        7: 'Tedaj veli Gospod Mojzesu: Pojdi, stopi doli! Zakaj tvoje ljudstvo, ki si ga pripeljal iz dežele Egiptovske, se je skazilo.',
        8: 'Hitro so zašli s pota, ki sem ga jim zaukazal: naredili so si ulito tele in se poklanjali pred njim in mu darovali, govoreč: To je bog tvoj, o Izrael, ki te je pripeljal iz dežele Egiptovske.',
        9: 'In reče Gospod Mojzesu: Videl sem to ljudstvo, in glej, trdovratno ljudstvo je;',
        10: 'sedaj torej me pusti, da se vname srd moj zoper nje in jih pokončam; tebe pa storim v velik narod.',
        11: 'Mojzes pa milo prosi Gospoda, Boga svojega, govoreč: Zakaj, o Gospod, se vnema srd tvoj zoper ljudstvo tvoje, ki si ga peljal iz dežele Egiptovske z veliko močjo in z roko mogočno?',
        12: 'Zakaj naj bi govorili Egipčani: Za nesrečo jih je izpeljal, da jih pomori v gorah in zatre s površja zemlje? Obrni se od togote srda svojega in žal ti bodi hudega zoper ljudstvo svoje.',
        13: 'Spomni se Abrahama, Izaka in Izraela, hlapcev svojih, ki si jim prisegel pri sebi in jim rekel: Pomnožim seme vaše kakor zvezde na nebu in vso to deželo, ki sem o njej govoril, dam zarodu vašemu, da jim je v dedno last vekomaj.',
        14: 'In žal je bilo Gospodu hudega, o katerem je bil govoril, da stori svojemu ljudstvu.',
        15: 'In Mojzes se obrne in stopa doli z gore, držeč dve plošči pričevanja v roki svoji, plošči popisani na obeh straneh: na tej in na oni strani je bilo pisano.',
        16: 'In plošči sta bili delo Božje, in pisava je bila pisava Božja, vdolbena v plošči.',
        17: 'In Jozue, ko je začul krik ljudstva, ki je ukalo, reče Mojzesu: Bojno vpitje je v taboru.',
        18: 'On pa reče: To ni glas takih, ki ukajo zaradi zmage, ne glas takih, ki vpijejo v poboju; glas pevajočih slišim jaz.',
        19: 'In zgodi se, ko se približa taboru in zagleda tele in ples, da se razsrdi in vrže plošči iz roke in ju razbije pod goro.',
        20: 'In vzame tele, ki so ga bili naredili, in ga sežge v ognju in ga zdrobi v prah in iztrese v vodo in jo da piti sinovom Izraelovim.',
        21: 'In Mojzes reče Aronu: Kaj ti je storilo to ljudstvo, da si nadnje pripravil velik greh?',
        22: 'Aron pa reče: Ne razvnema naj se jeza gospoda mojega! Saj poznaš ljudstvo, da je hudobno.',
        23: 'Rekli so mi namreč: Naredi nam bogove, ki naj gredo pred nami, zakaj tistemu možu Mojzesu, ki nas je pripeljal iz dežele Egiptovske, ne vemo, kaj se mu je prigodilo.',
        24: 'Jaz pa sem rekel: Kdo ima zlata? odtrgali so si ga in mi dali, in vrgel sem ga v ogenj, in izšlo je to tele.',
        25: 'In Mojzes je videl ljudstvo, da je razuzdano, kajti Aron ga je spravil v razuzdanost, v škodoželjen zasmeh pri sovražnikih njegovih.',
        26: 'Tedaj se postavi Mojzes med vrati v tabor in kliče: Sem k meni, kdor je Gospodu na strani! In zbero se k njemu vsi sinovi Levijevi.',
        27: 'In jim veli: Tako pravi Gospod, Bog Izraelov: Pripašite vsak meč svoj in pojdite semtertja, od vrat do vrat v taboru, in ubijte vsak brata svojega in vsak prijatelja svojega in vsak soseda svojega.',
        28: 'In storili so sinovi Levijevi po besedi Mojzesovi; in padlo jih je tisti dan izmed ljudstva blizu tri tisoč mož.',
        29: 'In Mojzes reče: Posvetite se danes Gospodu, da, vsak proti sinu svojemu in proti bratu svojemu, da pripravite danes blagoslov nad sebe.',
        30: 'In zgodi se drugega dne, da reče Mojzes ljudstvu: Pregrešili ste se z velikim grehom; in sedaj hočem iti gori h Gospodu, morda dosežem pomirjenje za greh vaš.',
        31: 'Vrne se torej Mojzes h Gospodu in reče: Ah, pregrešilo se je to ljudstvo z velikim grehom, ko si je naredilo boga iz zlata.',
        32: 'In sedaj, o da bi odpustil njih greh! če pa ne, izbriši me, prosim, iz knjige svoje, ki si jo pisal!',
        33: 'In Gospod reče Mojzesu: Kdorkoli je grešil zoper mene, njega izbrišem iz knjige svoje.',
        34: 'In sedaj pojdi, vodi ljudstvo tja, kamor sem ti povedal. Glej, angel moj pojde pred teboj; ali v dan obiskovanja svojega bom na njih kaznoval njih greh.',
        35: 'In Gospod je udaril ljudstvo, zato ker so naredili tele, ki ga je napravil Aron.',
    },
    33: {
        1: 'In Gospod je govoril Mojzesu: Vstani, potuj gori odtod, ti in ljudstvo, ki si ga pripeljal iz dežele Egiptovske, v deželo, o kateri sem prisegel Abrahamu, Izaku in Jakobu in govoril: Semenu tvojemu jo hočem dati;',
        2: 'In pošljem angela pred teboj in izženem Kanaance, Amorejce in Hetejce in Ferizejce, Hevejce in Jebusejce;',
        3: 'potuj v deželo, v kateri teče med in mleko; zakaj jaz ne pojdem med vami, ker si trdovratno ljudstvo, da te ne pokončam kje na potu.',
        4: 'In ko je ljudstvo slišalo to hudo poročilo, so žalovali, in nihče ni oblekel lepotine svoje.',
        5: 'Zakaj Gospod je bil rekel Mojzesu: Reci sinovom Izraelovim: Ljudstvo trdovratno ste vi; ako bi šel en trenotek med vami, bi te pokončal. In sedaj odloži lepotičje svoje, da bom vedel, kaj naj ti storim.',
        6: 'In sneli so sinovi Izraelovi lepotičje s sebe pri gori Horebski.',
        7: 'In Mojzes vzame šator in si ga razpne zunaj tabora, daleč od taborišča, in ga je imenoval: Šator shoda. In bilo je, da je vsakdo, ki je iskal Gospoda, hodil k šatoru shoda, ki je bil zunaj tabora.',
        8: 'In kadarkoli je šel Mojzes ven k Šatoru, je vstalo vse ljudstvo, in vsakteri je stal ob vhodu šatora svojega in gledal za Mojzesom, dokler ni stopil v Šator.',
        9: 'Ko je pa Mojzes stopil v Šator, je prišel doli oblakov steber in stal ob vhodu Šatora, in Gospod je govoril z Mojzesom.',
        10: 'In videlo je vse ljudstvo oblakov steber ob vhodu v Šator; in vse ljudstvo je vstajalo in se poklanjalo, vsak ob vhodu šatora svojega.',
        11: 'In Gospod je govoril z Mojzesom iz obličja v obličje, kakor govori človek s prijateljem svojim. Potem se je vrnil v tabor; njegov strežnik pa, Jozue, sin Nunov, mladenič, ni šel iz Šatora.',
        12: 'In Mojzes reče Gospodu: Glej, ti mi velevaš: Vodi to ljudstvo gori, a nisi mi ga dal spoznati, koga pošlješ z menoj, čeprav si rekel: Poznam te po imenu, in našel si milost v mojih očeh.',
        13: 'Zdaj torej, če sem našel milost v tvojih očeh, mi pokaži pot svojo, da te spoznam in vem, čemu najdem milost v tvojih očeh; in glej, ta narod je tvoje ljudstvo.',
        14: 'On pa reče: Obličje moje te bo spremljalo, in dam ti pokoj.',
        15: 'In Mojzes mu reče: Ako nas ne bo spremljalo obličje tvoje, ne pelji nas iz tega kraja.',
        16: 'In po čem naj bo vendar očitno, da sem našel milost v tvojih očeh, jaz in ljudstvo tvoje? Ne li po tem, da hodiš z nami in smo odlikovani, jaz in ljudstvo tvoje, izmed vseh ljudstev, kar jih je na površju zemlje?',
        17: 'In Gospod reče Mojzesu: Tudi to reč, ki si jo govoril, hočem storiti, kajti našel si milost v mojih očeh in poznam te po imenu.',
        18: 'On pa reče: Pokaži mi, prosim, slavo svojo!',
        19: 'In odgovori: Storim, da pojde mimo tebe vsa dobrota moja, in klical bom ime Gospodovo pred teboj; in milostiv bodem, komur hočem biti milostiv, in usmilim se, kogar se hočem usmiliti.',
        20: 'In reče: Ne moreš videti obličja mojega, zakaj človek me ne more videti in ostati živ.',
        21: 'In Gospod reče: Glej, prostor je pri meni, tu se postavi na skalo.',
        22: 'In zgodi se, ko pojde mimo slava moja, da te postavim v skalno razpoko in te pokrijem z roko svojo, dokler ne preidem mimo.',
        23: 'Potem odmaknem roko svojo, in videl me boš odzadaj, a obličja mojega ne bode videti.',
    },
    34: {
        1: 'In Gospod veli Mojzesu: Izsekaj si dve kameniti plošči, kakršni sta bili prvi, in napišem nanju besede, ki so bile na prvih ploščah, ki si ju razbil.',
        2: 'In bodi pripravljen za jutro, in stopi zjutraj na goro Sinajsko in se postavi pred menoj na vrhu gore.',
        3: 'Nihče naj s teboj ne gre gori, nihče naj se tudi ne prikaže po vsej gori, tudi drobnica in goved naj se ne paseta tej gori nasproti.',
        4: 'In izsekal je dve kameniti plošči, kakršni sta bili prvi; in vstal je Mojzes zjutraj zgodaj in šel na goro Sinaj, kakor mu je bil zapovedal Gospod, in v roko svojo je vzel dve kameniti plošči.',
        5: 'In Gospod je prišel doli v oblaku in je stal ondi poleg njega in klical ime Gospodovo.',
        6: 'In Gospod je šel mimo njega in klical: Gospod, Gospod, Bog mogočni, poln usmiljenja in milostiv, počasen za jezo in obilen v milosti in resnici,',
        7: 'ki hrani milost tisočim, ki odpušča krivico in prestopek in greh, ki pa krivega nikakor ne šteje za nedolžnega, ki obiskuje očetov krivico nad sinovi in vnuki, nad tretjim in četrtim pokolenjem.',
        8: 'In Mojzes se hitro pripogne k zemlji in moli.',
        9: 'In reče: Če sem našel milost v tvojih očeh, o Gospod, naj gre, prosim, Gospod sam med nami; zakaj to ljudstvo je trdovratno; in odpusti krivico našo in greh naš in vzemi nas za svojo last.',
        10: 'In odgovori: Glej, jaz sklepam zavezo: vpričo vsega ljudstva tvojega hočem delati čudeže, kakršnih ni bilo storjenih na vsej zemlji in med vsemi narodi; in vse ljudstvo, med katerim bivaš, bo videlo delo Gospodovo; kajti strašno bode to, kar bom delal pri tebi.',
        11: 'Hrani, kar ti danes zapovedujem. Glej, izganjam pred teboj Amorejce in Kanaance in Hetejce in Ferizejce in Hevejce in Jebusejce.',
        12: 'Varuj se, da ne skleneš zaveze s prebivalci dežele, v katero prideš, da ti ne postanejo zanka v sredi tvoji;',
        13: 'temuč njih oltarje poderite in njih poslikane stebre zdrobite in njih Ašere posekajte, –',
        14: 'kajti drugemu bogu se ne smeš poklanjati, zakaj Gospod, čigar ime je Gorečnik, je goreč Bog; –',
        15: 'da ne skleneš zaveze s prebivalci dežele, in ko bi nečistovali za svojimi bogovi in darovali bogovom svojim, bi te kdo povabil in ti bi jedel od njih daritve,',
        16: 'in jemal bi njih hčere za svoje sinove, in njih hčere bi nečistovale za svojimi bogovi in zapeljale sinove tvoje, da nečistujejo za njih bogovi.',
        17: 'Ulitih bogov si ne delaj! –',
        18: 'Praznik opresnikov obhajaj! Sedem dni boš jedel opresnike, kakor sem ti zapovedal, določeni čas v mesecu Abibu: kajti meseca Abiba si odšel iz Egipta.',
        19: 'Vse prvorojeno bodi moje, in vsa živina tvoja moškega spola, prvenci govedi in drobnice.',
        20: 'Prvorojeno oslice pa odkupi z jagnjetom, a če ga ne odkupiš, zlomi mu šijnjak. Vsakega prvenca izmed sinov svojih odkupi. In nihče naj se prazen ne prikaže pred obličjem mojim.',
        21: 'Šest dni delaj, sedmi dan pa počivaj; ob času oranja in ob času žetve počivaj. –',
        22: 'In praznik tednov obhajaj, prvin žetve pšenične, tudi praznik spravljanja ob koncu leta.',
        23: 'Trikrat v letu se naj prikažejo vsi moški tvoji pred obličjem Gospoda Jehove, Boga Izraelovega.',
        24: 'Kajti izženem narode pred teboj in razširim meje tvoje; nihče tudi ne poželi dežele tvoje, ako se pojdeš prikazat pred obličjem Gospoda, Boga svojega, trikrat v letu. –',
        25: 'Ne smeš darovati krvi klalne daritve moje s skvašenim kruhom vred; tudi naj ne ostane daritev praznika pashe čez noč do jutra.',
        26: 'Zemljišča svojega prve prvine prinesi v hišo Gospoda, Boga svojega. Kozliča ne kuhaj v mleku matere njegove.',
        27: 'In Gospod reče Mojzesu: Napiši si te besede, kajti po glasu teh besed sem sklenil s teboj zavezo in z Izraelom.',
        28: 'In bil je tam pri Gospodu štirideset dni in štirideset noči, in kruha ni jedel in vode ni pil. In Gospod je napisal na plošči besede zaveze, desetero besed.',
        29: 'In ko je potem šel Mojzes doli z gore Sinajske in je imel tisti dve plošči pričevanja v roki, ko je stopal z gore – ni vedel Mojzes, da se obraz njegov žari, ker je bil govoril ž Njim.',
        30: 'Aron pa in vsi sinovi Izraelovi gledajo Mojzesa, in glej, koža obličja njegovega se žari; in bali so se k njemu približati.',
        31: 'A Mojzes jih pokliče, in vrnejo se k njemu Aron in vsi knezi občine; in Mojzes je govoril ž njimi.',
        32: 'In potem pristopijo vsi sinovi Izraelovi; in zapove jim vse, kar mu je Gospod govoril na gori Sinaju.',
        33: 'In ko je Mojzes končal svoj govor ž njimi, dene zagrinjalo na obličje svoje.',
        34: 'Kadar pa je šel Mojzes noter pred obličje Gospodovo ž njim govorit, je snel zagrinjalo, dokler ni šel ven; in ko je bil prišel ven, je govoril sinovom Izraelovim, kar mu je bilo ukazano.',
        35: 'In sinovi Izraelovi so videli obličje Mojzesovo, da se je žarila koža obličja njegovega; in Mojzes je zopet del zagrinjalo na obličje svoje, dokler ni šel noter govorit ž Njim.',
    },
    35: {
        1: 'In Mojzes zbere vso občino sinov Izraelovih in jim reče: Te so besede, ki jih je zapovedal Gospod, da jih izpolnjujte.',
        2: 'Šest dni naj se opravlja delo, a sedmi dan vam bodi svet čas, sobota slovesnega počitka Gospodu; kdorkoli opravlja kak posel ta dan, umrje.',
        3: 'Ne zanetite ognja po vseh prebivališčih svojih sobotni dan!',
        4: 'Dalje govori Mojzes vsej občini Izraelovih otrok: To je beseda, ki jo je zapovedal Gospod, govoreč:',
        5: 'Odločite si dar povzdignjenja Gospodu; kdorkoli je radovoljnega srca, naj ga prinese, dar povzdignjenja Gospodu: zlato in srebro in bron,',
        6: 'višnjevo in zagorelordeče blago in karmezin in tenčico in kozjo dlako,',
        7: 'in rdeče pobarvane ovnove kože in kože jazbečeve in akacijev les,',
        8: 'in olje za svetilo in dišave za mazilno olje in za dišeče kadilo,',
        9: 'in onihove kamene in drago kamenje, ki se ž njim obloži naramnik in naprsnik.',
        10: 'In kdorkoli je modrega srca med vami, naj pride in izdeluje vse, kar je zapovedal Gospod:',
        11: 'prebivališče, njega šator in odejo za njega, njegove zapone in deske in zapahe in stebre in podstavke;',
        12: 'skrinjo in njena droga, pokrov sprave in ločilno zagrinjalo;',
        13: 'mizo in droga zanjo in vso posodo njeno in kruh obličja;',
        14: 'svečnik za svetilo in njegove priprave in svetilnice in olje za svetilo;',
        15: 'in kadilni oltar in droga zanj, mazilno olje in blagodišeče kadilo, zaveso za vhod, za vhod v prebivališče;',
        16: 'in oltar za žgalne daritve ž njegovim bronastim omrežjem, njegova droga in vse priprave njegove, umivalnik z njegovim stojalom;',
        17: 'zastore za dvorišče in stebre njegove in njih podstavke in zaveso za vrata na dvorišče;',
        18: 'kolčke za prebivališče in kolčke za dvorišče in njih vrvi;',
        19: 'dična oblačila za službo v svetišču, sveta oblačila za Arona duhovnika in oblačila sinom njegovim za duhovniško službo.',
        20: 'In vsa občina sinov Izraelovih se razide izpred Mojzesa.',
        21: 'In pridejo, kogarkoli je sililo srce njegovo, vsak, čigar duh je bil radovoljen, in prineso Gospodov dar povzdignjenja za zgradbo shodnega šatora in za vse službovanje pri njem in za sveta oblačila.',
        22: 'In prihajali so možje in žene, kolikorkoli jih je bilo radovoljnega srca, noseč zapestnice in uhane in pečatne prstane in ovratnice, vsakovrstno zlatnino, in vsakdo, ki je daroval dar majanja od zlata Gospodu.',
        23: 'In vsak, kdor je imel višnjevo in zagorelordeče blago in karmezin in tenčico in kozjo dlako in rdeče ovnove kože in jazbečeve kože, jih je prinesel.',
        24: 'Vsak, kdor je poklonil dar povzdignjenja od srebra in brona, je prinesel dar Gospodov; in kdorkoli je imel akacijevega lesa za katerokoli napravo službe, ga je prinesel.',
        25: 'In vse žene, ki so bile modrega srca, so predle same in prinesle prejo: višnjevo in zagorelordečo in karmezin in tenčico.',
        26: 'In vse žene, ki jih je podpiralo njih srce v modrosti, so predle kozjo dlako.',
        27: 'Knezi so pa prinesli onihovih kamenov in dragega kamenja, ki se ž njim obloži naramnik in naprsnik,',
        28: 'in dišav in olja za svetilo in za mazilno olje in za blagodišeče kadilo.',
        29: 'Sinovi Izraelovi so prinesli prostovoljno daritev Gospodu: vsak mož in vsaka žena, katere je izpodbujalo njih srce, da kaj prineso za vse delo, o katerem je Gospod zapovedal Mojzesu, da naj se izgotovi.',
        30: 'In Mojzes reče sinovom Izraelovim: Glejte, Gospod je po imenu poklical Bezalela, sina Urija, sinu Hurovega, iz rodovine Judove,',
        31: 'in ga je napolnil z duhom Božjim, ki se kaže v modrosti, razumnosti in znanosti in v vsakršni spretnosti,',
        32: 'da izumlja umetnine ter jih izdeluje iz zlata in srebra in brona',
        33: 'in zna rezati kamene, da se denejo v okove, in izrezavati les in delati vsakovrstne umetne izdelke.',
        34: 'Dal mu je tudi v srce, da poučuje, njemu in Oholiabu, sinu Ahisamakovemu, iz rodu Danovega.',
        35: 'Napolnil ju je z modrostjo srca, da napravita vsakovrstno delo kovaško in rezbarsko in umetno tkano in pisano vezeno iz višnjeve in zagorelordeče in karmezinove preje in iz tenčice in tkalsko delo, kakor tisti, ki delajo vsakovrstna ročna dela in izmišljajo umetne stvari.',
    },
    36: {
        1: 'In Bezalel in Oholiab bosta delala in vsi možje modrega srca, ki jim je Gospod dal modrost in razumnost, da znajo delati vsako delo v službo svetišča, skladno z vsem, kar je bil zapovedal Gospod.',
        2: 'In Mojzes pokliče Bezalela in Oholiaba in vsakega moža, ki je bil modrega srca, v čigar srce je Bog dal modrost, vsakega, kogar je srce sililo, da se loti dela in ga izvrši.',
        3: 'In prejmejo od Mojzesa vse dari povzdignjenja, ki so jih prinesli sinovi Izraelovi za delo v službo svetišča, da se s tem naredi. In še so mu prinašali prostovoljne darove dan na dan.',
        4: 'In pridejo tisti modri možje vsi, ki so se pečali z delom svetišča, vsak od svojega dela, ki ga je opravljal,',
        5: 'in ogovore Mojzesa, rekoč: Mnogo prinaša ljudstvo, več nego je treba za izvršitev dela, ki ga je napraviti ukazal Gospod.',
        6: 'Tedaj zapove Mojzes, in razglasijo po vsem taboru, rekoč: Ne mož, ne žena naj nič več ne dela za dar povzdignjenja svetišču. In nehalo je ljudstvo prinašati.',
        7: 'Kajti gradiva je bilo dovolj za vse delo, da se dogotovi, in še preveč ga je bilo.',
        8: 'Vsi torej, ki so bili modrega srca med delavci tistega dela, so delali prebivališče: deset preprog iz sukane tenčice in višnjevega in zagorelordečega blaga in karmezina, s kerubi umetno pretkane so jih naredili.',
        9: 'Dolgost ene preproge osemindvajset komolcev in štiri komolce širjava preproge: ista mera za vse preproge.',
        10: 'In zvezal je pet preprog, drugo ob drugo, tudi drugih pet preprog je zvezal, drugo ob drugo.',
        11: 'In naredil je pentlje iz višnjevega blaga na robu ene preproge, ob kraju ene zveze; enako je naredil na robu skrajne preproge pri drugi zvezi.',
        12: 'Petdeset pentelj je napravil na prvi preprogi in petdeset pentelj na robu preproge, ki je bila skrajna pri drugi zvezi; pentlje so bile druga drugi nasproti.',
        13: 'In naredil je petdset zapon iz zlata in staknil preprogi, prvo z drugo, s temi zaponami: tako je bilo prebivališče celota.',
        14: 'In naredil je preproge iz kozje dlake, da bodo šator nad prebivališčem: enajst takih preprog je naredil.',
        15: 'Dolgost vsake preproge je bila trideset komolcev in širjava štiri komolce: isto mero je imelo enajst preprog.',
        16: 'In staknil je pet preprog posebe in šest preprog posebe.',
        17: 'In naredil je petdeset pentelj na robu skrajne preproge v prvi zvezi in petdeset pentelj na robu skrajne preproge v drugi zvezi.',
        18: 'In napravil je petdeset bronastih zapon, da se ž njimi spoji šator v celoto.',
        19: 'In naredil je odejo za šator iz rdečih ovnovih kož in odejo iz jazbečevih kož vrhu nje.',
        20: 'In naredil je deske za prebivališče iz akacijevega lesa, pokonci stoječe.',
        21: 'Deset komolcev je bila dolgost vsake deske, eden in pol komolca pa širjava.',
        22: 'Vsaka deska je imela dva čepa, drug proti drugemu vstavljena: tako je napravil pri vseh deskah za prebivališče.',
        23: 'In izgotovil je deske za bivališče: dvajset desek za poldansko stran, proti jugu;',
        24: 'in naredil je štirideset podstav iz srebra za dvajset desek: dve podstavi pod eno desko za dva čepa njena in dve podstavi pod drugo desko za dva čepa njena.',
        25: 'In za drugo stran prebivališča, proti severu, je naredil dvajset desek',
        26: 'in njih podstav iz srebra štirideset: dve podstavi pod eno desko in dve podstavi pod drugo desko.',
        27: 'In za zadnjo stran prebivališča, proti zahodu, je naredil šest desek.',
        28: 'In dve deski je naredil za vogla prebivališča ob zadnji strani.',
        29: 'In bili sta dvojni odspodaj in enako sta bili sklenjeni ob vrhu svojem v enem obodu: tako je napravil pri obeh na obeh voglih.',
        30: 'Bilo je torej osem desek in njih podstav srebrnih šestnajst: pod vsako desko dve podstavi.',
        31: 'In naredil je zapahe iz akacijevega lesa: pet za deske ene strani prebivališča',
        32: 'in pet zapahov za deske druge strani in pet zapahov za deske ob zadnji strani, proti zahodu.',
        33: 'In srednji zapah sredi desek je naredil, da je segal od konca do konca.',
        34: 'In deske je prevlekel z zlatom in njih obode, namreč shrambice za zapahe, je naredil iz zlata in zapahe je okoval z zlatom.',
        35: 'In napravil je zagrinjalo iz višnjevega in zagorelordečega in karmezinovega blaga in iz sukane tenčice; s kerubi umetno pretkano ga je naredil.',
        36: 'In zanj je napravil štiri stebre iz akacijevega lesa in jih prevlekel z zlatom, njih kavlji so bili iz zlata, in ulil je zanje štiri podstave iz srebra.',
        37: 'In napravil je zaveso za šatorov vhod iz višnjevega in zagorelordečega blaga in iz karmezina in sukane tenčice s pisanim vezenjem',
        38: 'in njenih pet stebrov ž njih kavlji; oglavja stebrov pa in njih vezila je prevlekel z zlatom, a njih petero podstavkov je bilo iz brona.',
    },
    37: {
        1: 'In Bezalel je naredil skrinjo iz akacijevega lesa: dva in pol komolca je bila dolga in poldrugi komolec široka in poldrugi komolec visoka.',
        2: 'In prevlekel jo je s čistim zlatom odznotraj in odzunaj in vrhu nje je napravil zlat venec naokrog.',
        3: 'In zlil je zanjo štiri zlate obode, vstavljene v njene štiri noge, dva oboda na eni strani in dva oboda na drugi strani.',
        4: 'In naredil je droga iz akacijevine in ju okoval z zlatom.',
        5: 'In vtaknil je droga v obode ob straneh skrinje, da se prenaša skrinja.',
        6: 'In napravil je pokrov sprave iz čistega zlata, dva in pol komolca dolg in poldrugi komolec širok.',
        7: 'In naredil je dva keruba iz zlata s tolkljanim delom na obeh koncih spravnega pokrova:',
        8: 'kerub je bil na tem koncu, kerub na drugem koncu; s pokrovom sceloma je naredil tista keruba na obeh njegovih koncih.',
        9: 'In keruba sta razprostirala svoje peruti navzgor, zaslanjajoč ž njimi pokrov sprave, z obrazoma drug proti drugemu; proti pokrovu sprave sta bili obrnjeni obličji kerubov.',
        10: 'Naredil je tudi mizo iz akacijevega lesa: dva komolca je bila dolga in en komolec široka, poldrugi komolec pa visoka.',
        11: 'In prevlekel jo je s čistim zlatom in ji napravil zlat venec naokrog.',
        12: 'In naredil je k njej spojno deščico kroginkrog, za dlan široko, in napravil je zlat venec k tej deščici naokrog.',
        13: 'In ulil je zanjo štiri obode iz zlata, in pritrdil je obode na štiri vogle pri štirih miznih nogah.',
        14: 'Tik pod deščico so bili obodi, shrambici za droga, da se prenaša miza.',
        15: 'In napravil je droga iz akacijevega lesa in ju okoval z zlatom, da se ž njima prenaša miza.',
        16: 'In naredil je iz čistega zlata posode, ki so bile na mizi, njene sklede, torila, konvice in vrčke, s katerimi se naj izliva pitna daritev.',
        17: 'Naredil je tudi svečnik iz čistega zlata, tolkljano delo je bil s podstavkom in deblom svojim; čašice njegove, glavice in cvetice njegove so bile sceloma delane ž njim.',
        18: 'In šestero vej se je raztezalo iz debla njegovega: tri veje z ene strani in tri veje z druge strani svečnika.',
        19: 'Tri čašice, slične mandeljnovemu cvetu, so bile z glavico in cvetico na eni veji, in tri čašice, slične mandeljnovemu cvetu, z glavico in cvetico na veji drugi: tako je bilo na šesterih vejah, raztezajočih se iz svečnika.',
        20: 'In na deblu svečnika štiri čaše, slične mandeljnovemu cvetu, s svojimi glavicami in cveticami,',
        21: 'namreč ena glavica pod vsakima dvema vejama, katerih se je raztezalo šest iz celote, iz svečnika.',
        22: 'Njih glavice in veje so bile sceloma delane ž njim: vse je bilo enotno tolkljano delo iz čistega zlata.',
        23: 'In naredil mu je sedem svetilnic in utrinjala in lončke za utrinke iz čistega zlata.',
        24: 'Iz enega talenta čistega zlata ga je naredil in vse njegove priprave.',
        25: 'In naredil je kadilni oltar iz akacijevega lesa: en komolec dolgost njegova in en komolec širjava njegova, štirivoglat je bil in dva komolca visok; rogovi njegovi so bili enotni ž njim.',
        26: 'In prevlekel ga je s čistim zlatom, vrh njegov in stene njegove in rogove njegove, in mu je naredil zlat venec kroginkrog.',
        27: 'In napravil je zanj dva oboda iz zlata, pod vencem njegovim, ob voglih njegovih na obeh straneh, da se vanju vtakneta droga, s katerima se bo nosil.',
        28: 'In droga je naredil iz akacijevega lesa ter ju prevlekel z zlatom.',
        29: 'In naredil je sveto olje za maziljenje in čisto, blagodišeče kadilo na mazilarski način.',
    },
    38: {
        1: 'In naredil je oltar za žgalščine iz akacijevega lesa: pet komolcev dolg in pet komolcev širok, štirivoglat in tri komolce visok;',
        2: 'in na štirih voglih njegovih je na pravil štiri rogove, ki so bili iz ene celote ž njim; in prevlekel ga je z bronom.',
        3: 'In naredil je vse priprave oltarjeve: lonce in lopate in čaše, vilice in ponve za žerjavico; vse te priprave so bile iz brona.',
        4: 'Napravil je tudi omrežje oltarju, mrežastega dela, iz brona, pri obrobnem podstavku, spodaj do polovice oltarja.',
        5: 'In zlil je štiri obode za štiri vogle bronastega omrežja, da se vanje vtakneta droga.',
        6: 'Droga pa je naredil iz akacijevega lesa ter ju prevlekel z zlatom.',
        7: 'In vtaknil je droga v oboda na obeh straneh oltarja, da se ž njima prenaša; votlega, iz desek ga je naredil.',
        8: 'In naredil je umivalnik in stojalo njegovo iz brona, iz zrcal žen, ki so se zbirale, da strežejo pri vhodu shodnega šatora.',
        9: 'In napravil je dvorišče. Za poldansko stran, proti jugu, je bilo zastorov iz sukane tenčice sto komolcev',
        10: 'in dvajset stebrov zanje in dvajset podstavkov iz brona, kavlji za stebre in njih vezila iz srebra.',
        11: 'In na severni strani je bilo sto komolcev zastorov in zanje dvajset stebrov in dvajset podstavkov iz brona, kavlji za stebre in njih vezila so bili iz srebra.',
        12: 'In na zahodni strani je bilo petdeset komolcev zastorov in zanje deset stebrov in deset podstavkov, kavlji za stebre in njih vezila so bili iz srebra.',
        13: 'In na jutranji strani, proti vzhodu, petdeset komolcev:',
        14: 'petnajst komolcev zastorov ob eni strani vhoda, trije stebri zanje in trije podstavki;',
        15: 'in ob drugi strani (tu in tam ob vratih na dvorišče) petnajst komolcev zastorov, trije stebri in trije podstavki zanje.',
        16: 'Vsi zastori ob dvorišču kroginkrog so bili iz sukane tenčice;',
        17: 'in podstavki stebrov iz brona, kavlji za stebre in njih vezila iz srebra in prevlaka njih oglavij iz srebra; in vsi stebri ob dvorišču so bili opremljeni s srebrnimi vezili.',
        18: 'In zaveso k vratom na dvorišče je naredil z umetno pisanim vezenjem iz višnjevega in zagorelordečega in karmezinovega blaga in iz sukane tenčice, in to dvajset komolcev dolgo in pet komolcev visoko po širjavi, skladno z drugimi zastori ob dvorišču;',
        19: 'k zavesi pa štiri stebre in štiri podstavke iz brona in kavlje zanje iz srebra, tudi prevlako za njih oglavja in njih vezila iz srebra.',
        20: 'In vsi kolčki za prebivališče in ob dvorišču okoli so bili iz brona.',
        21: 'To je preračun o prebivališču, prebivališču pričevanja, kakor se je preštelo po Mojzesovem povelju s pomočjo levitov pod roko Itamarja, sinu Aronovega, duhovnika.',
        22: 'Bezalel pa, sin Urija, sinu Hurovega, iz rodu Judovega, je naredil vse, kar je bil Gospod zapovedal Mojzesu;',
        23: 'in ž njim je bil Oholiab, sin Ahisamakov, iz rodu Danovega, kovač in tesar in umeten tkalec in vezec višnjevega in zagorelordečega blaga in karmezina in tenčice.',
        24: 'Vsega zlata, kar se ga je uporabilo pri delu za vse naprave svetišča, zlata, ki se je darovalo kot daritev majanja, je bilo devetindvajset talentov, sedemsto in trideset seklov, po seklu svetišča.',
        25: 'Srebra pa od preštetih v občini je bilo sto talentov in tisoč sedemsto in petinsedemdeset seklov, po seklu svetišča:',
        26: 'kolikor glav, toliko polseklov, po seklu svetišča, od vsakega dvajset let starega in več, ki je prešel k preštetim, od šeststo in tri tisoč, petsto in petdeset mož.',
        27: 'In iz sto talentov srebra so ulili podstavke svetišču in podstavke zagrinjalu, sto podstavkov iz sto talentov, talent za podstavek.',
        28: 'In iz tisoč sedemsto in petinsedemdesetih seklov je naredil kavlje za stebre in prevlekel njih oglavja in napravil na njih vezila.',
        29: 'In brona, ki so ga darovali kot daritev majanja, je bilo sedemdeset talentov in dvatisoč in štiristo seklov.',
        30: 'In iz tega je naredil podstavke vhodu v shodni šator in bronast oltar in k njemu bronasto omrežje in vse priprave oltarjeve;',
        31: 'in podstavke ob dvorišču okoli in podstavke k vratom v dvorišče in vse kolčke pri prebivališču in vse kolčke na dvorišču kroginkrog.',
    },
    39: {
        1: 'In iz višnjevega in zagorelordečega blaga in karmezina so napravili dična oblačila za službo v svetišču; in sveta oblačila Aronu so naredili, kakor je bil Gospod zapovedal Mojzesu.',
        2: 'In naredili so naramnik iz zlata, iz višnjevega in zagorelordečega blaga in iz karmezina in iz sukane tenčice.',
        3: 'In zlato so skovali v tenke liste ter iz njih rezali niti, da se je moglo tkati med višnjeve in škrlatne in karmezinove niti in med tenčico, na način umetnega tkalca.',
        4: 'Naredili so za naramnik dva poramna dela, ki sta se spenjala; na svojih dveh koncih se je sklepal v eno.',
        5: 'In umetno tkana preveza, ki je bila ob njem, je bila iz istega blaga in enakega dela kakor naramnik: iz zlata, iz višnjevega in zagorelordečega blaga in karmezina in iz sukane tenčice, kakor je bil Gospod zapovedal Mojzesu.',
        6: 'In napravili so onihova kamena, opletena z zlatom, in vanju so bila vrezana, kakor se vrezuje v pečate, imena sinov Izraelovih.',
        7: 'In deli so ju na poramna dela naramnikova, da bodeta kamena spomina za sinove Izraelove, prav kakor je bil Gospod zapovedal Mojzesu.',
        8: 'In naredil je naprsnik, delo umetnega tkalca, istega dela kakor naramnik: iz zlata, višnjevega in zagorelordečega blaga in karmezina in iz sukane tenčice.',
        9: 'Štirivoglat je bil; naredili so ga v dve gubi, ped dolg, in pet širok, dvojnat.',
        10: 'In obložili so ga s štirimi vrstami kamenov; vrsta prva: sardij, topaz in smaragd;',
        11: 'in druga vrsta: rubin, safir in diamant;',
        12: 'tretja vrsta pa: hiacint, ahat in ametist;',
        13: 'in četrta vrsta: krizolit, onih in jaspis; opleteni so bili z zlatom v svojih vrstah.',
        14: 'In kamenov je bilo po imenih sinov Izraelovih dvanajst, po njih imenih; kakor se vrezuje v pečate, na vsakem je bilo vrezano ime, za dvanajstere rodove.',
        15: 'In naredili so na naprsnik vrvčasti verižici, spleteni iz čistega zlata.',
        16: 'In naredili so dva okova iz zlata in dva zlata obročka, in pritrdili so tista obročka na oba konca naprsnikova.',
        17: 'In dve spleteni zlati vrvci so pritrdili na dva zlata obročka na koncih naprsnikovih;',
        18: 'druga dva konca tistih dveh spletenih vrvic so pritrdili na dva okova in ju priteknili na poramna dela naramnikova, spredaj.',
        19: 'In iz zlata narejena dva obročka so priteknili na obeh koncih naprsnikovih, na robu njegovem, ki je proti naramniku, odznotraj.',
        20: 'Še so naredili dva zlata obročka in ju priteknili na dva poramna dela naramnikova, spodaj ob sprednji strani, ravno tam, kjer se sklepa, vrhu umetno tkane preveze naramnikove.',
        21: 'In privezali so naprsnik, njegove obročke k naramnikovim obročkom z višnjevo vrvico, da se gladko prilega nad umetno tkano prevezo naramnikovo ter da se naprsnik ne premakne z naramnika; prav kakor je bil Gospod zapovedal Mojzesu.',
        22: 'In naredil je vrhnjo suknjo pod naramnik, izcela stkano iz višnjevega blaga.',
        23: 'In odprtina suknje je bila sredi nje kakor odprtina pri oklepu, in je imela tvestje kroginkrog, da se ne razdere.',
        24: 'In za rob suknje so naredili margaranovih jabolk iz višnjevega, zagorelordečega in karmezinovega sukanca.',
        25: 'In napravili so zvončke iz čistega zlata in jih obesili med margaranova jabolka na rob suknje okoliinokoli, med margaranova jabolka:',
        26: 'zvonček in margaranovo jabolko, zvonček in margaranovo jabolko na rob suknje vseokoli za službo; prav kakor je Gospod zapovedal Mojzesu.',
        27: 'In izgotovili so spodnje suknje iz tenčice na tkalčev način Aronu in sinom njegovim;',
        28: 'in pokrivalo iz tenčice in lepe visoke čepice iz tenčice in platnene hlače iz sukane tenčice',
        29: 'in pas iz sukane tenčice in iz višnjevega, zagorelordečega blaga in iz karmezina, pisano vezilnega dela, prav kakor je bil Gospod zapovedal Mojzesu.',
        30: 'In naredili so ploščo, venec sveti, iz čistega zlata in vanjo napisali, kakor se vrezuje pisanje v pečate: SVETOST Gospodu!',
        31: 'In pripeli so nanjo višnjevo vrvico, da se ž njo priveže zgoraj na pokrivalo, prav kakor je bil Gospod zapovedal Mojzesu.',
        32: 'Tako je bilo dopolnjeno vse delo pri prebivališču shodnega šatora, in sinovi Izraelovi so ga naredili; kakor je bil Gospod zapovedal Mojzesu, prav tako so storili vse.',
        33: 'In prinesli so prebivališče k Mojzesu: šator in vse njegove priprave, njegove zapone, deske, zapahe, stebre in podstavke njegove;',
        34: 'in odejo za šator iz rdečih ovnovih kož in odejo iz jazbečevih kož in ločilno zagrinjalo;',
        35: 'skrinjo pričevanja in droga njena in spravni pokrov;',
        36: 'mizo, vso posodo njeno in kruh obličja;',
        37: 'čisti svečnik, svetilnice njegove, svetilnice, ki jih je imeti v redu, in vse priprave njegove in olje za svetilo;',
        38: 'zlati oltar in mazilno olje in blagodišeče kadilo; in zaveso za vhod v šator;',
        39: 'bronasti oltar z bronastim omrežjem njegovim, droga zanj in vse priprave njegove; umivalnik in stojalo njegovo;',
        40: 'zastore za dvorišče, stebre in podstavke zanj; in zaveso za vrata na dvorišče in vrvi in kolčke zanje; in vse priprave za službo v prebivališču, za shodni šator;',
        41: 'službena oblačila za službo v svetišču, sveta oblačila za Arona duhovnika in sinov njegovih oblačila, da duhovniško službo opravljajo.',
        42: 'Po vsem, kar je bil Gospod zapovedal Mojzesu, so sinovi Izraelovi napravili vse delo natanko.',
        43: 'In Mojzes je ogledal vse delo, in glej, prav so ga naredili; kakor je bil Gospod zapovedal, tako so ga napravili; in Mojzes jih je blagoslovil.',
    },
    40: {
        1: 'In Gospod je govoril Mojzesu, rekoč:',
        2: 'Prvi dan prvega meseca postavi prebivališče, shodni šator.',
        3: 'In postavi vanje skrinjo pričevanja in zasloni skrinjo z zagrinjalom.',
        4: 'In prinesi mizo v prebivališče in uredi na njej, kar je treba urediti, in prinesi svečnik in prižgi svetilnice njegove.',
        5: 'In postavi zlati oltar za kajenje pred skrinjo pričevanja in obesi zaveso k vhodu v prebivališče.',
        6: 'In postavi oltar za žgalščine pred vhod v prebivališče shodnega šatora.',
        7: 'In postavi umivalnik med shodni šator in oltar ter vlij vanj vode.',
        8: 'In postavi dvorišče okoli in obesi zaveso k vratom na dvorišče.',
        9: 'In vzemi mazilno olje ter pomazili prebivališče in vse, kar je v njem, in ga posveti in vso opravo njegovo; in bode sveto.',
        10: 'In pomazili oltar za žgalščine in vse priprave njegove in posveti oltar; in oltar bode presvet.',
        11: 'In pomazili umivalnik in stojalo njegovo ter ga posveti.',
        12: 'In privedi Arona in sinove njegove k vhodu shodnega šatora in jih umij z vodo.',
        13: 'In obleci Arona v sveta oblačila ter ga pomazili in posveti, da mi opravlja duhovniško službo.',
        14: 'Sinove njegove tudi privedi in jih obleci v spodnje suknje',
        15: 'in jih pomazili, kakor si pomazilil njih očeta, da mi opravljajo duhovniško službo. In njih maziljenje se zgodi, da jim ostane večno duhovništvo po njih prihodnjih rodovih.',
        16: 'In Mojzes je storil to; po vsem, kar mu je bil zapovedal Gospod, je storil prav tako.',
        17: 'In zgodilo se je prvi mesec drugega leta, prvi dan meseca, da je bilo prebivališče postavljeno.',
        18: 'In Mojzes je postavil prebivališče in zasadil podstavke njegove in postavil deske njegove in vtaknil zapahe njegove in postavil stebre njegove.',
        19: 'In razpel je šator čez prebivališče in del vrhu njega šatorovo odejo, prav kakor je bil Gospod zapovedal Mojzesu.',
        20: 'In je vzel pričevanje in ga položil v skrinjo in vtaknil oboda v skrinjo in je del spravni pokrov vrhu nje.',
        21: 'In prinesel je skrinjo v prebivališče, in ko je obesil ločilno zagrinjalo, je zaslonil skrinjo pričevanja, prav kakor je bil Gospod zapovedal Mojzesu.',
        22: 'In postavil je mizo v shodni šator na stran prebivališča proti severu, zunaj pregrinjala;',
        23: 'in je razporedil na njej vrsto kruhov pred obličje Gospodovo, kakor je bil Gospod zapovedal Mojzesu.',
        24: 'In postavil je svečnik v shodni šator, mizi nasproti, na južno stran prebivališča.',
        25: 'In prižgal je svetilnice pred Gospodom, kakor je bil Gospod zapovedal Mojzesu.',
        26: 'In postavil je zlati oltar v shodni šator pred pregrinjalo',
        27: 'in zažgal na njem blagodišeče kadilo, kakor je bil Gospod zapovedal Mojzesu.',
        28: 'In obesil je zaveso k vhodu v prebivališče.',
        29: 'In oltar za žgalščine je postavil pred vhod v prebivališče shodnega šatora in je daroval na njem žgalno in jedilno daritev, kakor je bil Gospod zapovedal Mojzesu.',
        30: 'In postavil je umivalnik med shodni šator in oltar in vlil vode vanj za umivanje.',
        31: 'In Mojzes in Aron in sinovi njegovi so si iz njega umivali roke in noge;',
        32: 'kadar so šli v shodni šator in kadar so se bližali oltarju, so se umivali, kakor je bil Gospod zapovedal Mojzesu.',
        33: 'in postavil je dvorišče okoli prebivališča in oltarja in je obesil zaveso k vratom na dvorišče. Tako je dopolnil Mojzes delo.',
        34: 'In oblak je pokril shodni šator, in slava Gospodova je napolnila prebivališče.',
        35: 'In Mojzes ni mogel iti v shodni šator, kajti oblak je počival nad njim, in slava Gospodova je napolnila prebivališče.',
        36: 'In kadar se je vzdignil oblak iznad prebivališča, so se odpravili sinovi Izraelovi na pot, dokler so bili na potovanju.',
        37: 'Ko se pa oblak ni vzdignil, se niso odpravili do dne, kadar se je vzdignil.',
        38: 'Zakaj oblak Gospodov je bil po dne na prebivališču, po noči pa ogenj v oblaku pred očmi vse hiše Izraelove, dokler so bili na potovanju.',
    },
}
